# نصوص كتاب الصف التاسع (Cycle 3) حرفيًا: O[stem] = [(مرجع الصفحة, النص)]
import re as _re
O = {}
O['T1-L06'] = [
 ('ص 20', 'والحق أن هذا السنع الأصيل ما كان له أن يستمر إلى يومنا هذا لو لم يكن ممزوجًا برمال الوطن، مسكونًا في قلوب أبنائه، مصانًا بحكمة شيوخه له في القصيدة مكان، وفي الزمن موعد مع قيام الاتحاد على يد القائد المؤسس الشيخ زايد بن سلطان آل نهيان -طيب الله ثراه، وإخوانه حكام الإمارات.'),
 ('ص 20 (ثالثًا: وحدة اللغة)', 'لقد شكلت اللغة العربية مقومًا أساسيًا من مقومات مجتمع الإمارات، فهي لغة السكان ووسيلة تواصلهم وتخاطبهم، وهي المستودع الفكري والوجداني لآمالهم وتطلعاتهم، دونوا تاريخهم، وحفظوا أشعارهم، وحكاياتهم، فكانت اللغة بحق معززًا حقيقيًا لوحدتهم، الاجتماعية والثقافية والسياسية.'),
 ('ص 20', 'واللهجة الإماراتية الدارجة هي لغة عربية، تميزت بغزارة مفرداتها، نتيجة ما حمله معهم الإماراتيون الأوائل من مفردات وتراكيب، جعلت اللغة المستخدمة تحمل هوية محلية فيما يمكن تسميته ب(لهجة الإمارات)، إلى جانب الهوية القومية التي تمثلها اللغة العربية الفصحى.'),
 ('ص 20', 'وما من شك في أن تعدد اللهجات وقدرتها على التكيف مع مراحل تطور المجتمع الإماراتي دليل على مرونة اللغة العربية، وقدرتها على استيعاب المفردات الجديدة وتطويرها كمصطلح جديد، من جانب آخر استطاعت اللغة العربية استيعاب كل ما يغني هذه اللهجات من أشكال الترادف في المعنى.'),
 ('ص 20', 'وفيما يتعلق بالعلاقة بين السنع واللهجة الإماراتية، يمكن القول: إن هذه اللهجة أسهمت في نقل مفردات السنع وعباراته بيسر وسهولة من جيل لآخر، فالجميع يتخاطب ويتواصل بلهجة مفهومة، ومتعارف عليها من حيث اللفظ والدلالة والمعنى.'),
]
O['T1-L07'] = [
 ('ص 21 (رابعًا: وحدة الدين)', 'يتميز الدين بتأثيره القوي في بناء القيم والاتجاهات، والمواقف والأفكار لدى المجتمعات، وكلها مقومات أساسية من مقومات وحدة المجتمع وتقاليده وأعرافه... ومن الحقائق الثابتة في هذا المجال أن العقيدة الدينية قد تسهم في ترسيخ منظومة معينة من القيم والعادات والتقاليد، وتتصدى لمنظومة أخرى وتلغيها.'),
 ('ص 21', 'وقياسًا على ذلك، فالإسلام هو دين الدولة الرسمي، فقد تعززت به وحدة العقيدة الدينية والاجتماعية في مختلف مظاهرها ومجالاتها. إذ غني عن القول أن الإسلام ليس مجرد عقيدة روحية أو مجموعة عبادات، وإنما هو دين شامل للحياة، يسعى بصفة خاصة إلى دعم الترابط الاجتماعي التي تشكل العادات والتقاليد والسنع بمفهومه الشامل أهم مقوماته.'),
 ('ص 21', 'وهكذا أصبحت الوحدة الدينية لمجتمع الإمارات عامل وحدة وتكافل في كل مظاهر الحياة الاجتماعية، ودافعًا لتحقيق المزيد من التطور والازدهار.'),
]
O['T1-L08'] = [
 ('ص 21 (خامسًا: وحدة الأصول)', 'يتجلى التجانس البشري في مجتمع الإمارات بكل وضوح، لأن معظم السكان من أصول عربية وفدت في فترات متعاقبة من مصدرين رئيسين، هما: شمال شبه الجزيرة العربية (العرب العدنانيون)، وجنوبها (العرب القحطانيون)، ووحدة الأصل هذه عززت على مر التاريخ بالعيش المشترك، والإرادة الموحدة لمواجهة التحديات والصعاب، والآمال العريضة بمستقبل واعد.'),
 ('ص 21', 'ولقد أسهم تاريخ الإمارات في صهرهم جميعًا في بوتقة الهوية الوطنية والعربية والإنسانية، والتي تشكل في عصرنا هذا دعامة أساسية من دعائم الوحدة الاجتماعية التي تشكل العادات والتقاليد والأعراف أبرز مظاهرها.'),
]
O['T1-L01'] = [
 ('ص 14 (أولًا: جهود القيادة الرشيدة في دعم السنع الإماراتي)', 'تحرص قيادتنا الرشيدة على ترسيخ السنع في نفوس الأجيال، وتعميق معناه في سلوكاتهم، من خلال منهج رصين ومتكامل يستمد أصوله من قيم سنع الأجداد العريق وتحقيق التنمية المستدامة في مجتمع الإمارات، وهذا السنع الشامخ بأهدافه، سلوك لا تكتمل الحياة اليومية إلا به، لطبيعته البسيطة والمنسجمة في سلوك الأفراد بقي بعيدًا عن كل أشكال التصنع، وسلوكًا يحياه الأفراد دون الحاجة للوعظ والإرشاد.'),
 ('ص 14', 'إن المنهج الرامي إلى إكساب الجيل الحالي والأجيال القادمة من أبناء الإمارات، قيم وتقاليد آبائهم وأجدادهم، مشروع تنموي بقدر ما هو مشروع ثقافي وحضاري، ذلك بأن بناء الفرد محور ومرتكز أساسي في استراتيجية قيادتنا الرشيدة، التي يقودُ ركبها صاحب السمو الشيخ محمد بن زايد آل نهيان رئيس الدولة -حفظه الله- وينسق صفوفها ويتابع رحلتها صاحب السمو الشيخ محمد بن راشد آل مكتوم نائب رئيس الدولة رئيس مجلس الوزراء حاكم دبي -رعاه الله، مكللة بالرعاية السامية والدعم اللامحدود والرؤية الواثقة بالمستقبل من إخوانهم حكام الإمارات.'),
 ('ص 14', 'وما من شك أن وطنًا مدعومًا بتراثه الأصيل، ثريًا بإنجازاته الواسعة، معززًا بقيادته الرشيدة، واثقًا بأبنائه، وطن جدير بالسمو والرفعة، وجدير بإعداد أجيال المستقبل التي تحافظ على هويته، وتستكمل مسيرته وسنعه.'),
]
O['T1-L02'] = [
 ('ص 14 (ثانيًا: تعريف السنع الإماراتي)', 'السنع أو المذهب، أو السمت أو المعاني، مترادفات في التراث الإماراتي لمجموعة القيم والتقاليد، وأنماط السلوك التي تعارف عليها أبناء المجتمع في دولة الإمارات العربية المتحدة، والتزموا بتطبيقها في الكثير من تفاصيل حياتهم، حتى باتت مكونًا مهمًا من مكونات هويتهم، وخصوصيتهم الثقافية والاجتماعية، تتناقلها الأجيال، وتحافظ عليها في إطار من الوعي بالمبادئ النبيلة، والقيم الأصيلة التي تنطوي عليها، والتي تسهم في مجملها بتهذيب النفس، والارتقاء بالسلوك، وغرس المثل السامية، والسمو بالمجتمع.'),
 ('ص 14', '(راعي سنع) أو (صاحب مذهب)، ذو صفات ترتقي به إلى درجات الرفعة، وتقربه إلى مراتب الكمال، أو الحسن من الأفعال، لهذا وصفت المعاجم والمصادر اللغوية السنع بصفات الجمال والحسن.'),
 ('ص 15', 'ويمكن حمل صفات السنع من دائرة الفرد، إلى دائرة الجماعة، ليقال أن هذه الأسرة راعية سنع، وأبناء ذاك المجتمع أصحاب سنع، لأنهم دأبوا على ممارسته، وتربوا على شمائله وطيب خصاله، من حيث دماثة الخلق، وطيب النفس، وحسن التعامل، وغير ذلك من جميل الصفات، وحسن المكارم.'),
 ('ص 15 (تعريف السنع)', 'هو مجمل الأقوال والأفعال والأخلاق الواجب الالتزام بها في المواقف الاجتماعية اليومية و المناسبات.'),
 ('ص 15', 'ومن يعرف أبناء الإمارات يدرك أنهم أصحاب سنع لما يتميزون به من صفات وقيم ومكارم خلقية عديدة، تتميز بالسلوك المتواضع، والاحترام المتبادل، والتعاون البناء، والسخاء، والكرم، والشجاعة، ونصرة المظلوم، والفزعة في المواقف التي تستدعيها في مساعدة الآخرين، والشهامة.'),
 ('ص 15', 'ولقد تربى أبناء الإمارات على هذه السمات من مكارم الخلق، وحسن التعامل مع الآخر، وحرصوا على نقلها من جيل إلى آخر، فأصبحت معيارًا أساسيًا لهويتهم الوطنية، وانتمائهم الأصيل، يُعرفون بها في أي مكان يحلون به.'),
 ('ص 15', 'وإضافة لهذه السمات القيمية العديدة التي تأصلت في التقاليد والسنع الإماراتي، فقد ترجمها الإماراتيون إلى أنماط من السلوك تربط بين الفعل أو القول والعمل، لهذا جاء سنعهم متماشيًا مع قيمهم وتقاليدهم، زد على ذلك إن ما يميز السنع الإماراتي انطلاقة أولًا من التزام القيادة ممثلة بأصحاب السمو الشيوخ والحكام والمسؤولين به، وحرصهم المستمر على استدامته، وجعله نهجًا وسلوكًا للجميع.'),
 ('ص 15', 'ولهذا حافظ الإماراتيون على سنعهم هذا، فبقي تقليدًا شاملًا في سلوكهم، ومعيارًا أصيلًا في ثقافتهم، يعتدون به، ويحرصون على نقله لأبنائهم وأحفادهم، بكل عز وشموخ.'),
]
O['T1-L03'] = [
 ('ص 16 (ثالثًا: لماذا نتعلم السنع؟ ولماذا نعلمه؟)', 'لماذا نتعلم السنع؟ أو لماذا نعلم السنع؟ وما من شك أن السؤال وأهميته تتجلى بأسباب ومبررات، يمكن بالوقت الراهن وسمها بالواجبات أو الضرورات التي تغدو اليوم أكثر إلحاحًا من أي وقت مضى، ومنها:'),
 ('ص 16', '1. القيمة المتنامية للتراث المعنوي في تشكيل الهوية الوطنية وتعزيز مقوماتها، وهنا لسنا بحاجة إلى التدليل بأن السنع، والعادات، والتقاليد، والموروث الشعبي فروعًا وأصولًا، شكلًا ومضمونًا، فكرًا وسلوكًا، هي التي تعبد لنا الطريق الواعد نحو المستقبل، وتجعل السير عليه آمنًا بلا معوقات.'),
 ('ص 16', '2. الأهمية البارزة للسنع في الحفاظ على العادات والتقاليد التي تبني السلوك الراقي، وتعزز مكارم الأخلاق، وهو لا ينحصر في أدب الكلام، وحسن التخاطب، التواصل مع الآخر، بل يمتد إلى السلوكات التي تبقى دائمًا، ومنها: الاهتمام بالمظهر العام، وآداب المجلس، وآداب الطعام، وبر الوالدين، وإغاثة الملهوف، واستقبال الضيف، واحترام الكبير، والعطف على الصغير، والرحمة واللين، وآداب السفر، والصدق والأمانة، والوفاء بالعهد، واحترام المواعيد، والمعاهدات، والتواضع، ولين الجانب، والكرم، وعدم الكبر.'),
 ('ص 16', '3. تقديم إطار وطني قيمي أخلاقي نابع من الدين والتراث المعنوي من أجل مجتمع إماراتي متماسك.'),
 ('ص 16', '4. عرض ومضات من فكر الآباء والأجداد ليمثل لهم القدوة والطريق القويم نحو العيش في مجتمع سليم.'),
 ('ص 16', '5. تعزيز الروابط الاجتماعية التي تؤدي إلى التجانس بين أفراد المجتمع.'),
 ('ص 16', '6. دعم الطلاب في التخلص من العادات غير المقبولة والسلوكات السلبية المرفوضة بإكسابهم أنماط سلوكية إيجابية سوية.'),
 ('ص 16', '7. إن اكتمال المعمار الحضاري والثقافي، والسير أبعد في مدارج النهضة والتطور والتقدم الذي تشهده دولة الإمارات العربية المتحدة وبناء منظومة القيم العادات والتقاليد وأنماط السلوك التي تربى عليها الأجداد والآباء وحافظوا عليها، بقيت تميزهم، وتبرز سماتهم، وكفاحهم في الحياة، وترسخ جذرًا عميقًا في تربة الوطن، يُواجه كل من يحاول انتزاعه من موطنه الأصيل.'),
]
O['T1-L04'] = [
 ('ص 18 (مقومات السنع في المجتمع الإماراتي)', 'لم يكن السنع الإماراتي وليد لحظة عابرة أو محصلة لحادث طارئ في المجتمع الإماراتي، إنما كان استجابة واعية وضرورية للظروف التي مر بها هذا المجتمع، والتي تفاعلت بها إرادة العيش والاستمرار في الحياة مع المقومات الجغرافية أو المكانية، والتجربة التاريخية الممتدة في استثمار الممكن أو المتاح من موارد الطبيعة في البر والبحر.'),
 ('ص 18', 'وفي إطار هذه المقدمات، تشكلت تجربة أبناء الإمارات الاجتماعية، وكان السنع الإماراتي منتج أصيل، في فصوله وأطواره، حكاية للبحر، وأخرى للصحراء.'),
 ('ص 18', 'وهذا البعض من منابع السنع الإماراتي وإن أسهم في إبراز خصوصية المجتمع الإماراتي في صنع تقاليده، ومفردات حياته، إلا أنه بقي يغذي هذه التقاليد ضمن مقومات أكثر اتساعًا وشمولًا، ومن أهمها:'),
 ('ص 18 (أولًا: وحدة المكان)', 'يشكل المكان أو الجغرافيا ركيزة مهمة من ركائز نشوء الدول وتطورها، فهو بخصائصه الطبيعية من حيث الشكل ومظاهر السطح والمناخ والمساحة والحدود والموارد عامل من عوامل وحدتها، وتيسير التواصل بين أقسامها، وذاكرة حية لنشاط المجتمع الذي عاش ويعيش فيها.'),
 ('ص 18', 'وهو من الوجهة الثقافية والتراثية والسجل الخالد للشعوب، تسطر في جباله وسهوله وبره وبحره تعبها وجهدها في إعماره وازدهاره.'),
 ('ص 18', 'ووفق هذا المفهوم الواسع للمكان أو الجغرافيا، يمكننا القول: إن تراث الإمارات وتاريخها القديم والحديث، بدأ بالتشكل والتكوين منذ أكثر من سبعة آلاف عام، رصدت الكثير منه حضارات عديدة تركت آثارها في العديد من المواقع والمستوطنات، مثل: أم النار، وحفيت، وهيلي، ومليحة، والبدية، والدور وغيرها ومع أن هذه المواقع تحكي لنا نشاط الإنسان في الجوانب التراثية المادية، إلا أنها مفيدة في الاستدلال على عمق هذا التراث ومقدمات التاريخ الحضاري لمجتمع الإمارات، في سبل العيش وأسلوب الحياة، باعتبارهما منتج من منتجات الزمان والمكان.'),
 ('ص 18', 'إن جغرافية دولة الإمارات العربية المتحدة رغم تعدد مظاهرها وتوزعها في العديد من البيئات: الساحلية، والصحراوية، والجبلية، والبحرية، ورغم أن كلًا منها أوجد طيفًا واسعًا من التقاليد والسنع والأعراف، فإنه من المؤكد أن ثنائية البر والبحر هي الأبرز في هذا التشكيل، أضاف لها ثراء وجمالًا في إطار متكامل استمرت معالمه حتى يومنا هذا.'),
]
O['T1-L05'] = [
 ('ص 19 (ثانيًا: وحدة الزمان)', 'عاش شعب الإمارات كغيره من شعوب وقبائل الوطن العربي، في مناطق صحراوية أو شبه صحراوية قاسية المناخ، شحيحة الموارد، غير أن هذه الظروف الصعبة، شكلت مبررات التعاون، والعمل المشترك، والعيش في إطار الجماعة بدءًا من الانتماء للأسرة الصغيرة فالأسرة الممتدة، ثم العشيرة والقبيلة... وهكذا بدأت بنية المجتمع وأسس تتكامل شيئًا فشيئًا، تحت لواء العشيرة والقبيلة، ثم الدولة بكامل أركانها ومقوماتها، رافق هذا كله تعزيز القيم والتقاليد الأصيلة التي توفر لها مقومات البقاء كالتعاون، والتسامح، والتضامن، والتكافل والإيثار، إلا أن هذه القيم ما كان لها أن تستمر وتكون فاعلة في المجتمع إن لم تعززها وتتكامل معها قيم أخرى كاحترام الجار، وصلة الرحم، وإكرام الضعيف.'),
 ('ص 19', 'وهكذا شكلت هذه القيم ردًا مناسبًا للمجتمع على قسوة الطبيعة وضعف مواردها المتاحة، وكانت حلًا ناجزًا لا مفر منه من أجل مواجهة تحديات المكان. وبقي المجتمع متسلحًا بها لمواجهة قسوة الزمان وتحدياته.'),
 ('ص 19', 'غير أن هذه المنظومة المتكاملة من القيم ما كان للمجتمع أن يستثمرها بكفاءة ونجاح في هذه المواجهة دون أن توجه خطاه قيادة واعية تمثلت بشيخ القبيلة الذي بقي دائمًا القائد، والراعي لشؤونها في السلم والحرب، جعل شيخ القبيلة أمام العديد من التحديات، ولا مفر أمامه غير إثبات قدرته على حماية القبيلة، وتعزيز قيمها، والانتقال بها من نجاح لآخر.'),
 ('ص 19', 'إن هذا الدور التكاملي بين مفهوم القبيلة ومفهوم المشيخة في المجتمع الإماراتي، جعل منها معززًا فاعلًا لمنظومة القيم التي تأصلت على مر الزمان في هذا المجتمع، وأظهر الحكام من الشيوخ اعتزازًا بالتراث المادي والمعنوي ومنه قيم السنع، والتزامًا به مثل غيرهم من أفراد المجتمع في خطوة رياديّة، وثقة عميقة بدور السنع في المحافظة على مقومات المجتمع، وسماته البارزة، وقيمه الأصيلة.'),
 ('ص 20', 'والحق أن هذا السنع الأصيل ما كان له أن يستمر إلى يومنا هذا لو لم يكن ممزوجًا برمال الوطن، مسكونًا في قلوب أبنائه، مصانًا بحكمة شيوخه له في القصيدة مكان، وفي الزمن موعد مع قيام الاتحاد على يد القائد المؤسس الشيخ زايد بن سلطان آل نهيان -طيب الله ثراه، وإخوانه حكام الإمارات.'),
]
O['T1-L09'] = [
 ('ص 22 (سادسًا: التجانس المجتمعي)', 'يقصد بالتجانس الاجتماعي، التماثل أو التشابه في النظم الاجتماعية، وفي العادات والتقاليد والأعراف الاجتماعية، فرغم الاختلاف النسبي في أنماط المعيشة بين سكان المدن، والقرى والبادية في الإمارات إلا أن منظومة متكاملة ومشتركة لا تزال تسير عجلة الحياة، وتشكل قاسمًا مشتركًا في العادات والتقاليد والأعراف، ومن أبرز مظاهرها المكانة التي يوليها المجتمع للأسرة القريبة والممتدة كرابط اجتماعي أساسي، والدور الذي يعوّل عليه المجالس في تعميق عرى التواصل والترابط الاجتماعي.'),
 ('ص 22', 'غير أن حدود التشابه لا تقف عند هذه الحدود من العادات والتقاليد والأعراف، بل تشمل المناسبات الاجتماعية كالزواج والاحتفال بالمناسبات الدينية والوطنية، وممارسة الرياضات، والأدب الشعبي بكل أشكاله وأنواعه، ولقد رأينا أن من عوامل هذا التجانس الاجتماعي، وحدة الجغرافيا، ووحدة التاريخ التي تجمع أبناء الإمارات في مكان واحد، ومخزون تاريخي متماثل.'),
 ('ص 22', 'لذا كان من الطبيعي أن نجد أسرًا وعشائر عديدة تنتمي للقبيلة الواحدة في مختلف الإمارات.'),
]
O['T1-L10'] = [
 ('ص 24 (القيم الأساسية في السنع الإماراتي)', 'ينهل السنع الإماراتي من منابع صافية، أسهمت في تشكيل منظومته في شتى مجالات الحياة، توارثتها الأجيال المتعاقبة على أرض الإمارات، ومما لا ريب فيه فإن هذه السلوكيات اكتسبت بمرور الزمن سمة الالتزام الطوعي، وكانت باستمرار متوافقة مع رؤية المجتمع وأعرافه وقيمه وتقاليده، وكلها أثبتت جدواها في تجارب الآباء والأجداد، وتم توظيفها بصورة عملية وإبداعية في نهضة الإمارات وتطورها.'),
 ('ص 24', 'ومع أن هذه القيم تحمل في خصائصها ومحتواها عوامل استدامتها، إضافة لقابليتها المستمرة للاكتمال والتطور، إلا أنها حظيت دائمًا بدعم مميز وتوجيه حثيث من القيادة الرشيدة بدولة الإمارات العربية المتحدة، في إطار إدراكها ووعيها الدائم بأهمية هذه القيم ومرتبتها المتقدمة في منظومة الأخلاق، ومسيرة النماء والتطور.'),
 ('ص 24 (أولًا: الكرم)', 'يقع الكرم في بداية القيم الأساسية التي تربى عليها أبناء الإمارات، وكما كان العربي مضرب المثل في الجود والعطاء وإكرام الضيف، بقي أبناء الإمارات أوفياء لدلال القهوة، والخيام المشرّعة للقريب والبعيد، وبقي الكرم قيمة أساسية لا مجال للمساومة على مكانتها ومنزلتها في مراتب القيم والتقاليد الاجتماعية.'),
 ('ص 24', 'ويسجل التاريخ أن كرم أبناء الإمارات فاض بالخير الوفير على أمم وشعوب أخرى، لا تزال تدين بالود والعرفان والجميل لإمارات الخير. كما يسجل التاريخ أن الكرم الذي جُبل عليه أبناء الإمارات وبقي علامة فارقة في تاريخهم القديم والحديث، اكتسب دفعًا خاصًا، ودعمًا أساسيًا من كريم العرب الشيخ زايد بن سلطان آل نهيان -طيب الله ثراه-، الذي فاض كرمه على الإنسان والطبيعة، يلبي دعوة المستغيث، ويكسو العاري، ويضمد الجراح، ويحارب الفاقة والحرمان، ويزرع البسمة.'),
 ('ص 24', 'ومن الأمثلة على كرمه -رحمه الله، يذكر المستشار أحمد الفضالي، في كتابه (زايد أسطورة العرب) أنه في إحدى جولات الشيخ زايد التفقدية لمنتزه المبزرة على سطح جبل حفيت، وبعد أن تجول بين الزوار والمتنزهين، وسر بما شاهده من سعادة بالخضرة والماء والطبيعة الجميلة، أمَرَ بأن يُقدمُ العشاء لكل زوار المكان، وماهي إلا فترة قصيرة حتى تم توزيع ثلاثة آلاف وجبة عشاء لكل المتواجدين.'),
 ('ص 25', 'وكَرَمُ الشيخ زايد -طيب الله ثراه- امتدَ للطيور، فها هو يُعجب أثناء زيارته لإحدى الدول الأوروبية بها، وهي تتزاحم على الطعام الذي يلقيه السياح، فيأمر بإعطاء أحد أصحاب المحلات المجاورة للمكان مبلغًا من المال يكفي لتقديم الطعام لهذه الطيور مدى عام كامل، وهذا الكرم الأصيل تعددت منافذه ومناسباته، كان -رحمه الله- يشعر بالسعادة والرضى عندما يجدُ الفرح والسعادة تعلو الوجوه كلما حقق للناس مطلبًا، أو لبى للمحتاجين حاجة.'),
]
O['T1-L11'] = [
 ('ص 25 (ثانيًا: الفزعة)', 'تعدّ الفزعة مظهرًا مهمًا من مظاهر الحياة الاجتماعية في دولة الإمارات العربية المتحدة، وتقليدًا أصيلًا مبني على التعاون والتكافل والمساندة في أوقات الشدة والحاجة للآخرين في النهوض بأعباء الحياة.'),
 ('ص 25', 'ومما يميز الفزعة أنها تطوع حر، ومبادرة تلقائية تُمليها القيم والتقاليد المتعارف عليها في المجتمع، دون أن يكون الدافع لها أجرًا ماديًا أو معنويًا، أو صلة قرابة أو أي اعتبارات أخرى.'),
 ('ص 25', 'والفزعة بمفهومها الاجتماعي قديمًا وحديثًا، فزعة في النفس لفعل الخير تجاه الآخر، ومد يد العون لمن يحتاج إليه، وهذه النزعة كانت ولا تزال من بين القيم والتقاليد الأصيلة في مجتمع الإمارات.'),
 ('ص 25', 'وهي وإن أصبحت اليوم أعمق مضمونًا، فقد حافظت على معانيها، وقيمها، وبقيت تغذي المجتمع بمعاني الأصالة،'),
 ('ص 25', 'في الماضي تجلّت الفزعة في هبة الجيران، وأبناء المجتمع في تقديم المساعدة في العديد من الأعمال من بينها موسم الحصاد. فما أن يُعلن عن أن شخصًا ينوي حصاد أرضه في زمن ومكان محددين، حتى تجد الكبير والصغير، الرّجل والمرأة، قد هبوا هبة رجل واحد لمساعدته، حاملين معهم القهوة والتمر والماء، وموزعين فيما بينهم المهام والمسؤوليات، فهذا يحصد الغِلال، وذاك يجمعها في حزم، وثالث يقوم بنقلها إلى أماكن جمع المحصول، خلية نحل متكاتفة ومتآزرة بهمة ونشاط.'),
]
O['T1-L11'] += [
 ('ص 26', 'وفي خَرْف (حصاد) الرطب يتكرر من جديد مشهد الفزعة، بعد أن ينادي المنادي أو صاحب النخل بأنه يحتاج للفزعة لجني أو خَرْف رطب مزرعته، فيتسابق الجار والبعيد، الصغير والكبير، للمساعدة ومدّ يد العون، مرددين الأهازيج الشعبية والقصائد.'),
 ('ص 26', 'وفي حمل الدعون الذي يستخدم في صناعة البيوت التقليدية، حيث ينادي المنادي أنه بحاجة لحمل دعن بو أربعة أو خمسة و ستة، بمعنى أنه بحاجة لهؤلاء الأشخاص في حمل كل نوع.'),
 ('ص 26', 'كما تتجلّى الفزعة في الانتقال من مكان لآخر، إذ يأتي الناس لفزعة من يود الارتحال، ومساعدته في نقل أثاثه وأمتعته، وأسرته، وفي أحيان كثيرة تبدو مظاهر الفزعة والنخوة المجتمعية في الأعراس والأتراح، وكأن الفرح والحزن هم اجتماعي لا ينحصر بأصحابه بل بالمجتمع ككل، وفي كلا الحالتّين تعم مظاهر الفرح، وتضيق دائرة الحزن والألم.'),
 ('ص 26', 'والمجتمع كما يقوم بواجب الفزعة تجاه القضايا المجتمعيّة الفردية، يقوم بها في القضايا العامة التي تتطلب من الجميع تحمل مسؤولياتها وواجباتها إزاءها.'),
 ('ص 26', 'والفزعة في الإعمار والبناء، والمناسبات الاجتماعيّة ومواجهة الأخطار في إطار من الشّهامة، والإيثار والمُخّوة إلى درجة بات الصّعب سهلًا، والحمل الثقيل ماديًا ومعنويًا سهل الحمل، يتقاسم حمله مجتمع النخوة والتكاتف، في شتى المناسبات، الكل مشارك في المسؤولية، وفزعة أبناء الإمارات هي التزام، وعقد اجتماعي، يزداد لحمة يومًا إثر يوم.'),
 ('ص 26', 'إن الفزعة التي تجذرت في التقاليد، والقيم الإماراتية منذ القدم، في البر والبحر، في الحل والتّرحال، استمرت حتى يومنا هذا منارة شامخة، وقيمة إنسانية سامية، بعد أن تجاوزت حدود الوطن، وجغرافية الإمارات إلى العالم أجمع، وأصبحت فزعة شعب الإمارات وقيادته في مواساة الشعوب، ونجدتها في كل مصاب أو كارثة إنسانية أو طبيعيّة، وفي التّخفيف عن مصابها في كل ما يلم بها من فقر وجوع وحرمان، أنموذجًا يُحتذى لما يمكن أن يقوم به الإنسان لأخيه الإنسان، ولما يمكن أن تتحمله الحكومات من واجبات تجاه الشعوب التي تتعثر في مسيرتها التنموّية والحياتية.'),
 ('ص 26', 'إن نقلة نوعيّة حصلت في مجال الفزعة على الصّعيدين المحلي والرسمي في دولة الإمارات العربية'),
 ('ص 27', 'المتحدة، نقلة رسم معالمها، واختط سيرها الشّيخ زايد بن سلطان آل نهيان -طيّب الله ثراه-، على مدى ستة قرون، ثم عمّق دروبها أصحاب السمو الشيوخ في إمارات الدّولة كافة. فأصبح للفقير، والمحتاج، بل الإنسان عامة، والطّبيعة، نصيبٌ من الفزعات التي تقوم القيادة الرّشيدة بدولة الإمارات، وشعبها، بها. وهذا نابعٌ من الإيثار الذي غرسته مدرسة زايد الخير في نفوس القادة وأبناء المجتمع، وتِلكُم محطات بارزة في مناهج هذه المدرسة وقيمها:'),
 ('ص 27 (يقول الشيخ زايد بن سلطان آل نهيان -طيب الله ثراه-)', '"في رأيي إن من يفعل شيئًا ويحصد من الخير هو وجماعته أو شعبه، يكون هو أحسن شيء يفعله الإنسان في حياته".'),
]
O['T1-L12'] = [
 ('ص 27 (ثالثًا: الترابط الاجتماعي)', 'بما أن المجتمع عبارة عن تشكيل يتكون من مجموع السكان الذين يعيشون على أرض واحدة، ومن مجموعة النظم والقيم والتراث والثقافة المشتركة، فإنه لابد له من أن يُبنى هذا التشكيل أو التكوين على علاقات راسخة بين أفراده وجماعته تؤدي في محصلتها إلى الترابط الاجتماعي الذي يكفل له مقومات الثبات والاستدامة.'),
 ('ص 27', 'حرص مجتمع الإمارات الذي ينتمي في أصوله الحضارية والتاريخية إلى الأصول العربية والإسلامية، عبر مراحل تطوره على المحافظة على العوامل التي تبني نسيجه الاجتماعي، وتعزز لُحمته الاجتماعية، وأعطى لهذا كله أهمية خاصة لتنظيم سلوك الفرد الاجتماعي من خلال معايير وقيم ارتضاها لنفسه وحافظ عليها من جيل إلى جيل.'),
 ('ص 27', '"إن المجتمع الإماراتي يشكل لحمة واحدة، فهو مجموعة من الأفراد والقبائل يعيشون في بقعة جغرافية واحدة، دينهم واحد، لغتهم واحدة، آمالهم وأحلامهم مشتركة، تاريخهم يجمع بينهم بخيوط من نور في الصّحراء، أو الجبال، أو في السهول، يحرصون على الارتباط بالآخرين؛ بأهلهم وعشيرتهم، علاقاتهم دينية واجتماعية وثقافية واحدة إن هذه اللحمة الاجتماعية الإماراتية، هي الّتي شكّلت في الماضي والحاضر حالة متقدمة في البناء الاجتماعي، وجسدًا واحدًا متحابًا، يقظًا في كل خطر، يملك دائمًا العزيمة والشّيمة للوقوف في وجه من يحاولُ النيلَ من وحدتهِ وعافيته".'),
]
O['T1-L13'] = [
 ('ص 28 (رابعًا: التسامح)', 'يحظى التسامح في الموروث الإماراتي بأصول وجذور بعيدة، وهو مفردة ثقافية وسلوكية مهمة في التقاليد والعادات والسنع بمفهومه العام.'),
 ('ص 28', 'كما أنه أحد الدعائم الأساسية التي شكلت الترابط والتعايش السلمي بين أفراد المجتمع، بحيث باتت الإمارات اليوم أنموذجًا للتسامح على مستوى العالم، تحتضن قيمه الأصيلة في قوانينها، ومؤسساتها الثقافية والاجتماعية والدينية، وتعززه ثقافةً وسلوكًا ونهجًا في الحياة.'),
 ('ص 28', 'ومن المعروف أن ديننا الإسلامي وأعرافنا وعلاقاتنا الاجتماعية حفلت منذ القدم بمعاني التضامن، والعيش المشترك، وعززت باستمرار علاقات التفاهم، والأمن والسلام، وعدم التمييز.'),
 ('ص 28', 'ويظهر هذا المناخ الإيجابي والفاعل لمفهوم السنع من كونه يتمثل في معناه البسيط: بسعة الصدر، وفتح قنوات التواصل مع الآخرين للتعبير عن آرائهم ومواقفهم، وهو في المضمار الديني دعوة صادقة ومباشرة لاحترام عقائد الآخرين وشعائرهم، وتيسير الأمور، وعدم الشدة والغلظة فيها.'),
 ('ص 28', 'ولأهمية التسامح ودوره في بناء السلم الاجتماعي والإنساني، وَرَد في القرآن الكريم والسنة النبوية في مواضع كثيرة، وأصبح من المسلم أن مؤشرات التسامح في حياتنا عديدة، منها: العفو عن الآخر، والصفح، والتسهيل، والتعايش المذهبي، والتعايش العقائدي بين أفراد المجتمع، واللين في المعاملة، والإيثار، والصبر، والحلم، والتيسير.'),
 ('ص 28', 'وهكذا جاءت الدعوة للتسامح صادقة في القرآن والسنة وهذه الدعوة يستظل تحتها ويُستهدف بها الناس جميعًا على اختلاف دياناتهم، ولغاتهم وجنسياتهم من خلال حسن التعامل، ورؤية فضائلهم.'),
 ('ص 28 (1- مجتمع الإمارات وسنع التسامح)', 'أضاف التسامح الذي تحلى به أبناء الإمارات قديمًا وحديثًا بُعدًا آخر لثقافتهم، وهم الذين عرفتهم أسواق التجارة، في كل مكان وصلوا إليه، بسهولة التعامل معهم، وإيثارهم، وصدقهم، وتسامحهم، وتواصلهم، وهم الباحثون عن الرزق في أعماق البحار، بدأب وصبر وتوكل.'),
 ('ص 28', 'لذا جاء سنعهم في التسامح تلقائيًا من غير تكلف، يترجم حياتهم، ويفتح في كل مرة صفحة من صفحاته المشرقة، لهذا يستغرب الشيخ زايد بن سلطان آل نهيان -طيب الله ثراه-، كيف لا يكون البعض منهم متسامحًا، حيث يقول: "نحن مسلمون، ولا نتسامح! هذا شيء غريب! إن المؤمن'),
 ('ص 29', 'يجب أن يكون رحيمًا ومتسامحًا، أما القاسي فهو الذي لا يرحم".'),
 ('ص 29', 'وفي إشارة إلى المضامين الفكرية لقيم التسامح ودورها في بناء المستقبل، يقول صاحب السمو الشيخ محمد بن راشد آل مكتوم، نائب رئيس الدولة رئيس مجلس الوزراء حاكم دبي -رعاه الله: "لا مستقبل لهذه المنطقة بدون إعادة إعمار فكري يرسخ قيم التسامح، والتعددية، والقبول، بالآخر فكريًا وثقافيًا وطائفيًا ودينيًا".'),
 ('ص 29', 'إن التسامح الذي نشأ عليه مجتمع الإمارات جزء من موروثه الذي كان -ولا يزال- يدعو إلى السلام والمودة والرحمة والتواصل والتآلف، وهذا ما يؤكده صاحب السمو الشيخ محمد بن زايد آل نهيان، رئيس الدولة -حفظه الله، بقوله: "الإمارات كانت وما زالت داعية سلام ورمز التسامح بين الشعوب".'),
 ('ص 29 (2- ثقافة التسامح في دولة الإمارات: خطوات وإنجازات)', 'بادئ ذي بدء لابد من التأكيد أن كل القوانين والتشريعات السائدة في دولة الإمارات، تؤكد روحًا ونصًا على الالتزام بالتسامح، والسلم، والتعددية الثقافية، وتجرّم الكراهية والعصبيّة والتفرقة.'),
 ('ص 29', 'الإمارات العربية المتحدة شريكٌ فعال في العديد من الاتفاقيات والمعاهدات التي تعمل على نبذ العنف والتّطرف والتمييز بين البشر. | العمل على تكريس نهج التسامح عبر إطلاق العديد من المبادرات العالمية حول التسامح. | تخصيص وزارة للتسامح في التشكيلة الوزاريّة، بدءًا من فبراير 2016. | أصدر الشيخ خليفة بن زايد آل نهيان -رحمه الله، مرسومًا بقانون (2) لسنة 2015 يقضي بمكافحة التمييز والكراهية، وكل ما من شأنه الازدراء بالأديان ومقدساتها، ونبذ خطاب الكراهية عبر مختلف وسائل وطرق التعبير. | إصدار قانون مكافحة التمييز والكراهية، لمكافحة الإرهاب، وحماية حقوق الأفراد وسلامتهم، وتحقيق الأمن والاستقرار، والتعايش السلمي في المجتمع. | اعتماد البرنامج الوطني للتسامح في يونيو من عام 2016 لدعم جهود دولة الإمارات العربية المتحدة لتنفيذ رؤية 2021، والأجندة الوطنية في مجال التعايش بين الأفراد وحقوق الإنسان، وتعزيز الثقافة والهوية الوطنية بما يُسهمُ في تعميق قيم الولاء والانتماء للوطن وقيادته. | إنشاء المعهد الدّولي للتسامح بناءً على القانون (9) لسنة 2017 الصّادر عن حكومة دبي، وإطلاق جائزة محمد بن راشد للتسامح وعدم التمييز بين الناس بسبب الدّين أو الجنس أو'),
 ('ص 30', 'العرق أو اللون أو اللغة، مع تكريم الأفراد والجهات التي تسهم في تعزيز قيمه بين أفراد المجتمع. | تأسيس جمعية الإمارات للتسامح والتعايش السلمي، بناءً على مخرجات مؤتمر الإمارات الدولي للأمن الوطني ودرء المخاطر المنعقد في أبوظبي عام 2018، تحت عنوان: (التسامح والوطنية والحوار في مواجهة التطرف). | استبدال اسم مسجد الشيخ محمد بن زايد آل نهيان في حي المشرف في أبوظبي باسم جديد بات يُعرف به، وهو مسجد (مريم أم عيسى)، علمًا بأن المسجد كان قد شُيّد عام 1985 في منطقة تشتمل على العديد من دور العبادة، حيث تقع على بعد أمتار منه كنيسة (القديس أندرو الإنجيلية).'),
 ('ص 30', 'الجدير بالذكر أن الشيخ زايد بن سلطان آل نهيان -رحمه الله- كان قد دعا إلى التسامح بين الأديان منذ وقتٍ مبكرٍ من التاريخ المعاصر لدولة الإمارات العربية المتحدة، حيث يقول ديفيد هيرد أحد ممثلي شركات النفط في أبوظبي: "لقد حضر الشيخ زايد بنفسه لتدشين أول كنيسة في الكورنيش، مما عزز في قلبي مدى الاحترام والتسامح الذي كان يتحلى به تجاه الأديان الأخرى، ونحن جميعًا ممتنون للشيخ زايد بهذا الجانب الآخر من شخصيته الذي أحاطنا به كمسيحيين وكإنجليز".'),
]
O['T1-L14'] = [
 ('ص 30 (خامسًا: الشجاعة ونصرة المظلوم)', 'ليست الشجاعة حالة مؤقتة في مجتمع الإمارات ولا مواقف منعزلة في تاريخهم، فهي قيمة أصيلة من القيم التي نشأوا عليها، وسلوك متجذر في حياتهم، تشكلت تفاصيله من شجاعتهم أولًا في التمسك بالمكان، رغم الظروف الطبيعية القاسية، والموارد المحدودة، وهذه الشجاعة هي قمة الشجاعات الأخرى التي توالت فيما بعد وسطرها شعب الإمارات في الكثير من ميادين الحياة، والقيم الأصيلة. وما الخير الذي ينعم به أبناء الإمارات اليوم في الأمن، والاقتصاد، والعيش الرغيد، إلا ثمرة من ثمار الصعود المستمر نحو القمة بكل شجاعة وإقدام، يكشف عن بعضها الشاعر الإماراتي المايدي بن ظاهر، بقوله:'),
 ('ص 30', 'إن الجميل صعبة مزقاتها لو ما صعوبتها رقاها الدنبلي'),
 ('ص 30', 'وما دام للشجاعة ميادينها فإن شعب الإمارات خاضوا هذه الميادين وخبروها بإرادة لا تلين، وكان رائدهم على الدوام إحقاق الحق، ونصرة المظلوم، مع الإيمان الراسخ بأن الشجاعة سلوك مطلوب،'),
 ('ص 31', 'ومقياس من مقاييس الرجولة في مواجهة الظلم، والحيلولة دون استمرار الخطأ.'),
 ('ص 31', 'يقول القائد المؤسس الشيخ زايد بن سلطان آل نهيان -طيّب الله ثراه-، في حديثه للشباب: "إن كل شر تتعرض له هذه الأمة، لابد أن نسهم في دفعه بأموالنا، ودماء شبابنا، وسلاح جنودنا، ولهذا أعددناكم، وأعددنا لكم كل وسائل القوة المتاحة التي تسمح بها إمكانياتنا".'),
 ('ص 31', 'غير أن الشّجاعة التي عرفها أبناء الإمارات في سنعهم الأصيل وموروثهم شجاعة الحق، ورد الاعتداء، ونصرة المظلوم، وكانت الدعوة للأمن والسلام، والإخاء بين الشعوب هي سمة السنع الإماراتي، وكل ما سواها آيل للزوال، يقول الشّيخ زايد بن سلطان آل نهيان -طيّب الله ثراه-: "كل من يطمع في حق الآخرين سيكون مصيره الفشل، وهذا ما تعلمناه من التاريخ، الدول التي قادت حركات الاستعمار، ماهو وضعها الآن؟ لقد تركت مستعمراتها، ولم تعد قادرة على الغزو، وأصبحت هذه المستعمرات دولًا مستقلة".'),
 ('ص 31', 'إن الشّجاعة ونصرة المظلوم التي شكّلت باستمرار مبادئ بارزة في التّراث والسنع الإماراتي، لم تتغير وتيرتها قط، ومن السّهولة بمكان أن نسوق الأمثلة الكثيرة الدّالة عليها في تاريخنا القديم والحديث، مجتمع الإمارات كان وما زال من أكثر المجتمعات التي سعت إلى مواجهة الظّلم، ودرء مخاطر العدوان، وإشاعة الأمن والسلام. ويسجل التاريخ أن مسيرة الشّيخ زايد بن سلطان آل نهيان -طيّب الله ثراه- في الحكم، كانت مكللة في رأب الصّدع بين القبائل، والوقوف في وجه العدوان، ومناصرة الحق في كل مكان،'),
 ('ص 31', 'ولم تقتصر هذه المشاركة في دفع الظّلم، ومناصرة المظلوم عند حدود الدّفاع والتّضحية بالنفس،'),
]
O['T1-L14'] += [
 ('ص 32', 'بل امتدت أياديهم البيضاء تضمد كل جرح، وتطعم كل جائع، وتدفع الخطر عن كل ضعيف.'),
 ('ص 32', 'وسيكتب التّاريخ أن تقاليد أبناء الإمارات سنعهم، وثقافتهم، جعلتهم دعاة للسلام، ورسلًا للعدل، وأنصارًا للمظلومين، وطريق الخير إلى:'),
 ('ص 32', 'سلالٍ من الخير والعطاء للأسر الجائعة في أكثر من مكان. | مدنٍ وقرى تُشاد لمن لا مأوى لهم. | إعادةِ إعمارٍ لمدن وقرى دمرتها آلة الحرب. | سدودٍ ومشاريعَ تقام لتسقي الزّرع والضّرع والإنسان. | مشافٍ ومصحّات تبعث الأمل والحياة لآلاف المرضى. | مدارسٍ ومعاهدَ تحارب الجهل، وتبني رجال المستقبل. | إغاثاتٍ عاجلةٍ لمجابهة المجاعات والكوارث.'),
 ('ص 32', 'بقي أن نشير إلى أن الشّجاعة ونصرة المظلوم تقليدان متداخلان في السّنع الإماراتيّ، فحيث تكون الشّجاعة تتولد القدرة على مساعدة المظلوم ونصرته.'),
 ('ص 32', 'وبالمقابل فإن نصرة المظلوم مظهر من مظاهر الشّجاعة، ومعيار رئيس من معاييرها.'),
]
# ملاحظة: الأبيات الشعرية في الكتاب لا تُنسخ هنا؛ يُحال إلى الصفحة.
O['T1-L15'] = [
 ('ص 34 (أولًا: السنع في نهج الشيخ زايد بن سلطان - رحمه الله)', 'قلما تلتقي أماني الشعوب وآمال الوطن بالقائد الذي يحمل الراية، ويصنع الانتصارات في شتى الأصعدة والمجالات، وطوبى لشعبٍ التقى يومًا بقائدٍ عظيم.'),
 ('ص 34', 'في عام 1946 كانت العين أول بقعةٍ من أرض الإمارات تحظى بلقاءٍ خاص بين آمالها وقائدها، إنه القائد الكبير الشيخ زايد بن سلطان آل نهيان - طيب الله ثراه.'),
 ('ص 34', 'آنذاك، أيقنَ زايد - طيّب الله ثراه، أن الدّرب طويل، والموارد محدودة، لكن بالمقابل هُناك الإرادةُ للتغيير، والرّؤيةُ لصنع المستقبل، وأن تجربة الحكم في العين كممثلٍ لأخيه الشيّخ شخبوط بن سلطان آل نهيان حاكم أبوظبي في (1928 - 1966) -طيّب الله ثراه، فيها من التّجارب والممارسات والمواقف ما يُمكنُ أن تصقلَ قدراتِه.'),
 ('ص 34', 'وهذا ما يُلخصه الشّاعر محمد بن حم العامري، بقوله: (بيت شعري في الكتاب)'),
 ('ص 34', 'وقد ارتكزت هذه التّجربة على مقوماتٍ ونهجٍ وتقاليد ليست بعيدة عن أسرته ومجتمعه وتاريخه، أسهمتْ في تذليلِ الصّعاب، وتشكيلِ أركانِ السَّنَعْ الذي تميّز به، وهي:'),
 ('ص 34 (1. السمات الدينية)', 'فقد كان -رحمه الله- مؤمنًا بانتمائه للدين السّمح، والقيم الأصيلة التي يدعو إليها، مع إيمانٍ متين بأن الله الذي خلق الكون والبشر قادرٌ على توفيرِ كل مقوّمات الحياة لهم، لذا كان دائمُ الشّكر والتّفاؤل، إذ يقول -رحمه الله: (أبيات شعرية في الكتاب)'),
 ('ص 34', 'وإيمان الشّيخ زايد - رحمه الله - يمكن أن يؤخذ مثالًا وأنموذجًا لفهم الإسلام الفهم السليم القائم على الوسطية والاعتدال، والقيم السمحة الّتي يُبِيَ عليها، لهذا كان داعمًا مستمرًا لتيار الوسطية،'),
 ('ص 35', 'وكان حريصًا كل الحرص على تقريب دُعاة الوسطية والسّلام من كبار العلماء الذّين توافدوا على إمارات الخير من كلّ بقاع العالم الإسلامي في شتّى المناسبات، لا سيما في شهر رمضان المبارك، وكان في لقاءاته الدّائمة معهم يدعوهم إلى أن ينشروا في أوطانهم قيمَ الإسلام السّمحة والأصيلة، ويحاربوا بالكلمة الطيبة، والوعظ الهادف، كل ألوان التّطرف والغلو، الذي لا ينتمي للدين الإسلامي بأي شكلٍ من الأشكال.'),
 ('ص 36 (2. الارتباط الأسري)', 'ارتبطَ الشّيخ زايد بن سلطان آل نهيان - طيب الله ثراه - بأسرته ارتباطًا وثيقًا، وكان وفيًا لهذه الأسرة، بدءًا بالعلاقة الخاصة بوالدّته التي بقيت على الدّوام موجهًا لسلوكه، ومساندًا قويًا للنجاحات التي يُحقّقُها في مسيرته القيادية، ولعلّ هذا الرّضى المميز من والدّته هو الذّي كان يشق طريقةُ نحوَ رضا الله ورضى المجتمع، وبالتّالي التوفيق والسّداد في كل أمور الحياة.'),
 ('ص 36', 'وكما كان وفيًا لوالدّته الشّيخة سلامة بنت بطي آل حامد -طيّب الله ثراها- كان أيضًا واصِلًا للرحم، عطوفًا على أخته الوحيدة الشّيخة مريم بنت سلطان آل نهيان -رحمهما الله، وعطوفًا بالقدر ذاته على إخوته وأقاربه، مؤمنًا بأن صلته القوية بهم مقدمةٌ ضرورية بصلته الواسعة بأبناء شعبه أو أسرته الوطنية الكبيرة، ومفتاحًا أوليًا لما ينتظره من مهام ومسؤوليات، وحسٍ عالٍ بالمسؤولية تجاههُم، ولكّم ترجم هذه المسؤولية في كل ما كان يصدر عنه من قرارات ومراسيم بتذييلها بعبارة: (والدّكم زايد بن سلطان آل نهيان).'),
 ('ص 36', 'وهكذا نظرَ زايد - رحمه الله - إلى شعبهِ على أنهُ جزءٌ من أسرتهِ الصّغيرة، وكما واجبُهُ السّهر على راحةِ أبنائها، وكسبِ رضاها وصلةِ أرحامِها، كان التزامُها عليه -رحمه الله- أن يسكبَ كلّ هذه العواطف والمشاعر والحب والوفاء والرّضى تجاه أسرته الكبيرة (شعب الإمارات).'),
 ('ص 36', 'فهو القائل -رحمه الله-: "أعتبر نفسي رَبَّ عائلة كبيرة هي الشّعب، وأن واجب رب العائلة أن يرعى شؤون أفراد عائلته، ويعمل على سعادتهم ورفاهيتهم".'),
 ('ص 36', 'والتّاريخ الذي يرصُدُ الصّفحات المضيئة لزايد - طيب الله ثراه - لا ينسى إن هذا القائد العظيم في أحْلكِ ظروفه ومعاناتِهِ الصّحية، كان دائم السّؤال عن شعبه، يقول معالي أحمد بن خليفة السّويدي الممثل الشّخصي له -رحمه الله- أنه في أحدِ المرّات التي كان المغفور له بإذن الله الشيخ زايد بن سلطان آل نهيان - رحمه الله - يرقُد في أحدِ المستشفيات في الخارج للعلاج، دخلتُ عليه فبادرني بالسّؤال: كيف أولادي؟، قلت له حينها: "خليفة وإخوانه كلهم بخير يا طويل العمر"، إلا أنني فوجئت به يقول: "أنا أسألك عن شعبي".'),
 ('ص 37', 'ولَكُمْ أن تتخيلوا أبعادَ هذه العاطفة واتساعِها: الشّعب كله حاضِرٌ في وجدان زايد - رحمه الله - وهو على سرير العلاج، بعيدًا عن الوطن.'),
 ('ص 37 (3. مجلس الشيخ زايد - رحمه الله)', 'شكّلت مجالسُ الشيوخ في الإمارات عمومًا ومجلسُ الشيخ زايد بن سلطان آل نهيان - طيب الله ثراه - خصوصًا عُرْفًا أصيلًا في علاقةِ الحاكم بشعبِه، فلطالما شكّلت منتدىً للحوار والتّشاور والاستفتاء على الكثيرِ من القضايا والقرارات قبلَ صُدورها، وحل العديد منها قبل نفاذِ الوقت.'),
 ('ص 37', 'والمجلس في عُرفِ زايد - رحمه الله - مدرسةٌ حقيقية يتعلم منها الحضور آدابَ الحديث والإنصات، وإبداء الرّأي، وتقليبِ الأمور من أوجهها المختلفة، كانت برزة الشّيخ زايد - رحمه الله - ومجلسه تفوحُ منهُ رائحةُ الطّيب، والألفة والكرم والمحبة والأنس والدّفء، كما تفوحُ منه رائحةُ القهوة وحُسنِ الاستقبال.'),
 ('ص 37', 'والبرزةُ التي كانت له يومًا تحت ظل شجرة أو حائطِ قصرٍ أو حصن أو فوق كُثَيِّبٍ رملي، استمرت على بساطتِها إلى جانب المجالس الحديثة المُجهزة بكلِ الإمكانيات الحديثة في قصوره ودواوينه وأماكنِ إقامته في الدّاخل والخارج، وهي النهج الذي اقتفى أثره وعزّزَ غاياتِه أولادُهُ أصحابَ السمو الشّيوخ، فلكلٍ مجلسُهُ وبرزتُه ونافذتُه على الشّعب، وعينُهُ المفتوحةُ على قضاياه ومسائله في كل شأن.'),
 ('ص 37 (والآن ما هو سنع الشيخ زايد - رحمه الله - في مجلسه؟)', 'أعطى الشّيخ زايد بن سلطان آل نهيان - طيب الله ثراه - مجلسَهُ قديمًا وحديثًا الطّابعَ الرّسمي في استقبال ضُيوفَهُ الوافدين من خارج الدولة وداخِلها، إلى جانب الطّابع الشّعبي التّقليدي في استقبال ضيوفَهُ من أبناءِ الشّعب.'),
 ('ص 37', '1- الضّيوفُ من حكّام الإمارات، وزُعماءِ الدّول يستقبلهُم من مدخل المجلس بالتّرحاب، ويصطحبهم إلى المكان المخصص لجلوسهم في صدر المجلس، يلي ذلك استهلالُ هذا اللقاء بمراسيمِ تقديم القهوة عنوانُ الضّيافة والكرم العربي، والمعروف أن قهوة الشّيخ زايد - رحمه الله - تتميز بلونها الدّاكن المخلوط بماء الورد والزّعفران، حيثُ جاءَ وصفُها على لسانِهِ -طيب الله ثراه-، بالأبيات الآتية: (أبيات شعرية في الكتاب)'),
 ('ص 38', '(أبيات شعرية في الكتاب)'),
 ('ص 38', 'أما الدلة القريشية التي تُقدّم فيها القهوة فقد أضحت دلةً مشهورة ترتبطُ بمجلسِه وبأسرة آل نهيان الكرام بصورة عامة، وبالتّراث الإماراتي الأصيل.'),
 ('ص 38', 'ومثلما يستقبلُ ضيفَهُ القادم بالترحاب والقهوة العربية والعُود، يودّعه بمثلِ ما استُقبِل به من حفاوةٍ وتَرْحاب.'),
 ('ص 38', '2- الضّيوفُ من أبناء الإمارات، كان معهم ذي حميميةٍ خاصة، لا حواجزَ ولا بروتوكولات.'),
 ('ص 38', 'حيث يُبادِرُ الشّيخ زايد - رحمه الله - بالاستفسار عن أهلهِ وعشيرتهِ ومنطِقتِه القادم منها وأحوال الناس، وحاجاتِهم بل أكثرُ من ذلك يستفسر عن الأمطار والنباتات في ديارهم، ومراعيهم، وهل كان عامهم عام خير وبركة، وبسؤالِ العارِف يسأل عن أحوال بعض الأشخاص في القبيلة، ذاكرًا أسماءهُم.'),
 ('ص 38', 'ومجلسُ الشّيخ زايد - أو برزتَه عَلاوةً على أنهُ كان مُشْرَعَ الأبواب أمام الضّيوف، ومكانًا مهمًا لمعرفةِ نبضِ المجتمع وأحواله، فقد كان مثالًا للكرم والضّيافة العربية تُقدّمُ فيه الوجبات الرّئيسة في حينها، وأحيانًا يُوفِّرُ للزائر أو الضّيف القادم من مناطق بعيدة، المبيت والإقامة التّي قد تمتدُ لأيامٍ عدة.'),
 ('ص 38', 'ومما يُثيرُ الانتباه بحق أن الشّيخ زايد بن سلطان آل نهيان - طيب الله ثراه - كانَ عطوفًا مُرْهَفَ الأحاسيس والمشاعر، إنسانًا في التّعامل مع الصّغيرِ والكبير، المرأة والرّجل، المسؤول وغير المسؤول، فقد وثّقَت وسائلُ الإعلام كيف كان يستمعُ للأطفال ويستجيبُ لطلباتِهم.'),
 ('ص 39 (4. مُخْوَةُ الشيخ زايد - رحمه الله)', 'مع أن المُخْوَةُ تقليدٌ اجتماعيٌ أصيل في مجتمع الإمارات، تُشيرُ معانيها وسلوكاتِها إلى لونٍ خاص من ألوان التّرابط الاجتماعي، إلا أن مُخْوَةَ الشّيخ زايد - طيب الله ثراه - لها طعمٌ خاص، أجْملَها الشّاعر أحمد بن علي الكندي المرر، في بيتٍ من الشّعر، قالهُ في إحدى رحلات القنص مع الشّيخ زايد - طيب الله ثراه: (بيت شعري في الكتاب)'),
 ('ص 39', 'كانَ -رحمه الله- حريصًا على إشاعةِ أجواءٍ من الود، وعدم التّكلّف، والبساطة بينهُ وبين مرافقيه أو صَحبِه لا سيما في جلسات السّمر التي كانت تُتوّجُ في كل يوم عمل أو نشاط في المقناص، وحتى في المهام الرّسمية.'),
 ('ص 39 (5. للعصا في سنع زايد - رحمه الله - قصة أخرى)', 'حَمّلَ زايد - رحمه الله - في حلّه وترحالِه عصًا من الخيزران، ساعدتهُ رغم بساطتِها في التّعبير عن أفكارِه ومشاريعِهِ وتطلُعاتِه، فكثيرًا ما كان يرسمُ بها جُزْءًا من أحلامه على الرّمال، إذ ينقُل المؤرخون عنه أنه كان يشرحُ لكبارِ المستشارين والمهندسين بهذه العصا، مخططات شبكات الطّرق، والرّي، والتّوزيع العمراني، ومواقع الجامعات والمؤسسات التّعليمية والمُنْشآتِ الطّبية، ومساحات الغابات الخضراء، ومثلما يوزع المهندس تصوراته لمنشأةٍ ما على الخرائطِ والورق، كانتَ العصا قلمُه -رحمه الله- لرسمِ أفكارِه ورؤيتِهُ للمستقبل على رمالِ الصّحراء.'),
 ('ص 39', 'الجديرُ بالذّكر أن حمل العصا كان من مستلزمات الذّرابة والسّمت الإماراتية والصّلابة، إذ يعاب على الرّجل في الماضي أن يدخُلَ مجلسًا أو يُشاركُ في مناسبةٍ اجتماعية من غير عصاه.'),
 ('ص 40 (6. الفخر والاعتزاز بالتراث الإماراتي)', 'يظهرُ تأثير القيادة ودورها البارز في تحديد سمات السنع الإماراتيّ ومكوناته، والمحافظة عليه من خلال القراءة المتأنية لمسيرة حُكْمِ الشّيخ زايد بن سلطان آل نهيان -رحمه الله- التي امتدت ما يقارب ستة عقود من حكمه لمدينة العين كممثل للحاكم فيها بين عامي (1946-1966)، واستكمالًا لحكمه إمارة أبوظبي (1966-2004)، ومن ثم دولة الإمارات العربية المتحدة بين عامي (2004-1971).'),
 ('ص 40', 'إنَّ للشيخ زايد والتّراث قصة من نوع آخر، فهو من ربط مستقبل شعب الإمارات بالمحافظة على التراث، بعبارة موجزة ومعبرة: "من لا ماضيِ له، ليس له حاضر ولا مستقبل"، وهو القائل أيضًا: "إن تفكيرنا في الماضي وعظاته، هو الّذي سيقودنا دائمًا إلى بناء وطننا وتقدمه ونهضته".'),
 ('ص 40', 'من هنا كان انحيازه -طيب الله ثراه- للتراث عامة، وللسنع خاصة انحيازًا تامًا، في الوقت الذّي وضع الحداثة والتّطوير نُصْبَ عينيه، وجعلها إلى جانب التراث منظومة متكاملة تبني المستقبل.'),
 ('ص 40', 'لقد أدرك الشّيخ زايد بن سلطان آل نهيان -طيب الله ثراه- بحسه القيادي الفذ، ونظرته المستقبلية النافذة، أن التراث مُكوّنٌ أساسي من مكونات النظام السّياسي، لذا لم يكن موجهًا للتمسك بالتراث ومفرداته من تقاليد وأعراف وسَنع وحسب، بل ممارسًا نشطًا في ترسيخه وتأكيد حضوره في المجتمع، فهو المبدع في الشعر النبطي لسان التّراث الجميل، وهو الصّقار والمعلم والمدرب، والخبير في هذه الرّياضة التّراثية العريقة.'),
 ('ص 40', 'وزايد -رحمه الله- فارس أصيل، ودارس وباحث ومتبصر بأصول القبائل وأنسابها، وسيّرها وإنجازاتها، وهو الموجه والمصوب لكل ما يتصل بالسّنَع الإماراتيّ من تقاليد وأعراف وممارسات مجتمعيّة، توجيه يرتقي إلى مستوى التّعليم كلما وجد الحاجة إلى ذلك، في مجلسه ولقاءاته، وأسفاره، إلى درجة جعل التّراث جزءًا مهمًا من خطابه السّياسي، بل برنامجه السّياسي على مستوى المجتمع ودوائر الدّولة ومؤسساتها.'),
 ('ص 40', 'إن من بين مآثر الشّيخ زايد بن سلطان آل نهيان -طيب الله ثراه- في مجال التّراث والسَّنَعِ الإماراتيّ، عمله الدّؤوب من أجل المحافظة على رموز هذا التراث، ومنها:'),
 ('ص 40', 'الرّياضات التراثية كرياضة الصيد بالصقور. | سباقات الهجن.'),
 ('ص 41', 'سباقات الخيول العربية. | المهرجانات التراثية.'),
 ('ص 41', 'فقد نظر -رحمه الله- إلى الصّقارة أو رياضة الصيد بالصّقور على أنها تقليد اجتماعي مهم، ومدرسة حقيقية يتعلم فيها الصّقارون جوانب كثيرة من سنعهم، وتقاليدهم، في التّعاون والإيثار والمحافظة على البيئة، والرّأفة بالطّير، والكرم، والصّبر، وآداب المجالس، والشّجاعة، وتحمل الصّعاب.'),
 ('ص 41', 'ويمكن الوقوف على المحطات البارزة في سَنَعْ زايد - رحمه الله - المرتبط بالتّراث في أكثر من دالة، وموقع وفق الآتي:'),
]
O['T1-L16'] = [
 ('ص 41 (1. زايد - رحمه الله - والخيل)', 'ارتبط الشيخ زايد - رحمه الله - بالخيول ورياضاتها منذ صِباه، فقد ألِفَ سكان مدينة العين زايد - رحمه الله - وهو على صهوة جوادِه، متفقدًا أحوال الواحات والنخيل والأفلاج، وهذا الارتباط بالخيول وسلالاتها ليس غريبًا عليه، إذ هو من سلالة عريقة احترفت ركوب الخيل وتعرفت على صفاتها وميادينها، ومآثرها، فجده زايد الأول ضرب أروع الأمثلة في الفروسية على ظهر الحصان ربدان، وكان له صولات وجولات مع هذا الحصان الأشم، من هنا أحبّ الشّيخ زايد - رحمه الله - ركوب الخيل، ودعا إلى تعلُّم ركوبها وإتقانِ المهارات المرتبطة بها، وأنزلها المرتبة التي تستحقها، بحيث أصبحت الإمارات من أبرز الدّول في العالم التي تعنى بتربية الخيول، وإقامة سباقاتها في ميادين يقصدها هواة هذه السّباقات من شتى أنحاء العالم.'),
 ('ص 41', 'زد على ذلك بأن الشّيخ زايد - طيب الله ثراه - كان خبيرًا بسلالاتِ الخيول، ووسائل تطويرها، بهدف الحفاظ على السّلالات الأصيلة منها، واختيار أجودها، وأنقاها، وأشدها قوة.'),
 ('ص 42', 'والفروسية التي اكتسبها زايد - رحمه الله - منذ صباه، هي التي أسهمت في تشكيل الكثير من صفاته الشخصية، فهو الفارس الشّجاع في أحلك الظّروف، وهو الذي تأصلت به فراسة العربي، في معالجة القضايا المحلية والعربية والدّولية.'),
 ('ص 42', 'وهو الفارس في ميادين السّياسة والشّعر والأدب، وهو وإن كان فارسًا في ميادين السّباق فقد كان فارسًا بحق في بلوغ الأهداف والاستراتيجيات والرّؤى والآمال، يُخطّط ويبلغُ الأهداف، يسيرُ ويصلُ إلى الغايات.'),
 ('ص 42', 'وهنا يقول رحمه الله: "الطّموحُ له طريقان، أولهما طموح الغرور، والثّاني طموح الواجب، والثّاني هو الطّموح الذي أسعى إليه دائمًا في إنجاز الأعمال، وهو طموحٌ توافقونني على أنه مطلوب وواجب، وخاصة إذا كان لخدمة شعبي".'),
 ('ص 42', 'وزايد - رحمه الله - الفارس هو الذي آثر مصلحة شعبه على كل المصالح، ووضعَ أبناء وطنه همّة الأول والأخير. وهل هناك دليل أفصح وأكثر مصداقية من قوله -طيب الله ثراه-: "إن اهتمام الإنسان بمصالحهِ وتحسين أوضاعَهُ الشّخصية، لا يجوز أن تكون هي الاهتمامات التّي يحرُص عليها الشّخص المسؤول في أي دولة كانت، لأن المطلوب منه في هذه الحالة أن يكون مسؤولًا بالدّرجة الأولى عن مواطنيه، وتحقيق الصّالح العام، وإذا اهتم هذا المسؤول بمصلحته الشّخصية، وأهمل المصلحة العامة، فإنه بهذا يقضي على المصلحتين معًا...".'),
 ('ص 42 (2. زايد - رحمه الله - والهجن)', 'وقفت الإبلُ إلى جانبِ أبناء الإمارات منذ القدم، تتحملُ معهُم جزءًا كبيرًا من معاناتِهم، فلا تبخلُ عليهم في التنقُل والتّرحال، ومصادرِ خيرها من ألبانِها، ولُحومِها، ووبرها، والأكثرُ من هذا كلّه كانت دافِعًا لقصائدهم وأشعارِهم وألحانِهم وحدائهِم، وكما أتقن الشّيخ زايد بن سلطان آل نهيان - طيب الله ثراه - فنونَ الفروسية، وأنزلَها منازل التّقدير والعرفان بفضائلها، أتقنَ أيضًا وبالقدرِ ذاتِه تربية الهجن وريّاضتها، وحثّ على اقتنائِها وتسنيعها، إما لأغراضِ السّباق أو للاستفادة من ألبانِها ولحومِها، وهو القائل في هذا الشّأن: (أبيات شعرية في الكتاب)'),
 ('ص 43', 'وفي سنعهِ المتعلق بالهجن، وضع -رحمه الله- ضوابطَ ومعايير وسلوكات لمربي الهجن وأصحابِها، ومن بينها: التّحدي الشّريف في السّباق. | عدم التّعالي والافتخار على الآخرين في حالِ الفوز. | عدم إيذاء المطيّة أثناء السّباق. | عدم استخدام الأطفال في ركوبها أثناء السّباق. | عدم إعطاء المطيّة المنشطات المحظورة. | الالتزام بفئات السّباق من حيث السّن والعمر. | دعم مؤسسات البحث العلمي، للمحافظة على السّلالات العربية الأصيلة.'),
 ('ص 43 (3. زايد - رحمه الله - والسّباقات البحرية)', 'شكّل البحر ميدانًا واسعًا في حياة أبناء الإمارات وأنشطتِهم الاقتصادية والثّقافية، ومن بينها الرّياضات المتعلقة به، وهذه الرّياضات قديمة قِدَمَ علاقاتهِم بالبحر، إذ كانت رَحّلات الغوص لا سيما في مرحلةِ القِفّال والعودة من مغاصات اللؤلؤ، تشهدُ سباقات تقليدية بين السّفن العائدة إلى البر، يحافظ من خلالها المتسابقون على تراثهم، وعلى لقاء الأهل والأحبة.'),
 ('ص 43', 'وزايد - رحمه الله - الّذي اعتز بتراثِه أيّما اعتزاز، أحْيا هذه السّابقات بقوة، فأنشأ أندية التّراث والجمعيات، ودعا إلى تنظيم العديد من السّباقات، ورصدَ لها الجوائز القيّمة، وكرّم هُواتها وممارسيها، وأغدق على صُنّاعِها بالدّعم المادي والمعنوي.'),
 ('ص 44', 'ومن السّنَعِ الّذي كرّسهُ زايد - رحمه الله - في هذا المجال: التزامُ المتسابقين بقياسات السّباق أو البوانيش (المراكب). | الالتزامُ بأنواعٍ معينة من الأشرعة. | الالتزامُ بمعايير ومسافات السّباق. | التّأكيدُ على روح الجماعة والفريقِ الواحد في هذه السّباقات من حيث الإعداد والتّدريب وبلوغ الأهداف.'),
]
O['T1-L17'] = [
 ('ص 44 (ثالثًا: السنع في فكر الشيخ زايد - رحمه الله)', 'لمْ يَكُنْ زايد بن سلطان آل نهيان - طيب الله ثراه - داعيًا وموجهًا وقائدًا للالتزام بالسَّنَعْ والمحافظة عليه فحسب، بل ممارسًا حقيقيًا لأشكال السَّنَعْ في حياته العامة والخاصة، فقد عرفه مجتمع الإمارات قدوةً ومثالًا يُحتْذَى به في التّمسكِ بالعادات والتّقاليد والسَّنَعْ الأصيل، وهذا ما جاء على لسانه -رحمه الله-، قائلًا:'),
 ('ص 44', '"حياتي الخاصة بسيطة جدًا، تخلو من التّعقيدات، أحب الطّبيعة والهواء الطّلق، وأكره كل ما هو اصطناعي، ويسرني أن أتسلى مع المجموعة التّي تعيش معي، أرفض أن أتناول الطّعام بدون الأصحاب والإخوة، والأكل على انفراد لا يعجبني، والجلسة على انفراد لا تعجبني، أحب الناس، وأتوق للحديث معهم دائمًا، في أوقات فراغي أتحدث مع أهلي، نجلس معًا، ونأكل، ونتبادل الحديث معًا".'),
 ('ص 44', 'إن التّحليل الموضوعي لوصف الشّيخ زايد - رحمه الله - لحياته الخاصة، يبرز كل ما نريده لمجتمع الإمارات من تمسك بالسَّنَعْ، والمحافظة عليه، ويعطي مثالًا كيف أن الطّريق للالتزام بالسَّنَعْ ينطلق أولًا من البساطة، وعدم التّكلف، والصّدق في الأسلوب، والتّعامل مع الآخرين.'),
 ('ص 44', 'ويتجلّى فكر زايد - طيب الله ثراه - في السَّنَعْ، بأجلى صوره ومعانيه في الشّعر، إذْ المعروف أن للشعر في فكره منزلةً خاصة، ومقامًا رفيعًا، فهو رفيقُ الشّعر النبطي.'),
 ('ص 44', 'وزايد الشّاعر - رحمه الله - هو الّذي أحب الشّعراء، وقربهم من مجلسه، وأكرمهم بكل أنواع الكرم'),
 ('ص 45', 'وأشكاله، ولم يقتصر اهتمامه بالشّعر النبطي فحسب، بل أحبّ الشّعر العربي الفصيح، ورموزه من شعراء قدامى ومحدثين، وفي طليعتهم الشّاعر المتنبي الّذي طالما تغنى بأشعاره مادحًا موهبتَهُ الشّعرية، ومستشهدًا بالعديد من قصائده في الحوارات والمناقشات الأدبية الّتي يعمر بها مجلسه في كل حين.'),
 ('ص 45', 'الشّيخ زايد بن سلطان آل نهيان، شاعر نبطي مرموق، له ديوان شعري مطبوع، قام بتحقيقه حمد أبو شهاب.'),
 ('ص 45', 'ولقد تناول الشّيخ زايد - رحمه الله - سَنَعْ المجتمع الإماراتي في العديد من الموضوعات، من بينها: التّأني والتّمسك بالقيم، وفيها يقول: (أبيات شعرية في الكتاب) | الحذر وعدم التّسرع، ومن أبياته في هذا السَنَعْ: (أبيات شعرية في الكتاب) | دعوة للشّباب للاجتهاد والعمل من أجل الوطن، وفيها يقول: (أبيات شعرية في الكتاب)'),
 ('ص 46', 'استمرار حفز قدرات الشّباب على بناء الوطن، وفيه يقول -رحمه الله-: (أبيات شعرية في الكتاب)'),
]
O['T1-L18'] = [
 ('ص 48 (سنع التواصل الاجتماعي)', 'يُعَدُّ البعد الأخلاقي ركنًا أساسًا في العملية التربوية، حيث يعجز أي كان عن الفصل بين الأخلاق والتّربية، وأدى التّطور الحاصل في مجال المعلوماتية على الصّعيد الاجتماعي، إلى تزايد الإقبال على استخدام تقنيات الاتصال والمعلومات كأداة لنشر المعلومات في وقتنا الحاضر، حيث تمكن تقنيات المعلومات والاتصال من نشر المعلومات، كما تمكن الأفراد من الحصول على المعلومات في أي زمان ومكان وحول أي موضوع يمكنهم استغلاله لتطوير أنفسهم اجتماعيًا وثقافيًا واقتصاديًا.'),
 ('ص 48', 'ودولة الإمارات العربية المتحدة من أوائل الدّول العربية الّتي انفتحت على مواقع التّواصل الاجتماعي، حيث مثلت أنموذجًا للمجتمع المنفتح على الثّقافات والحضارات الأخرى والمتفاعل مع التّطبيقات ونتائج ثورة الاتصالات والمعلومات مع حفاظها على السَّنَعْ وقيمه الأصيلة الذّي يُعَدُّ من مكونات الموروث الّذي رسم شخصية الإنسان الإماراتي وحدد ملامح هويته الوطنية وأساليب التّواصل وبناء العلاقات الاجتماعية وكيفية العيش والتّعامل مع الآخرين، حيث لم يترك الآباء والأجداد أي موقف من دون أن تكون له أصول وعادات حضارية متميزة يستحسن اتباعها، والتي يمكن إجمالها بالسّلوك الحميد الّذي يمثل القيم الأصيلة المتصلة بالترابط الاجتماعي والتّواصل الإنساني الّذي يحمل أبعاد أخلاقية ابتكرها المجتمع الإماراتي لنفسه منذ القدم.'),
 ('ص 48', 'وتؤدي وسائل التّواصل الاجتماعي دورًا كبيرًا في حياة الناس والمجتمع بما تمتلكه من ميزات تغلبت على حدود الزّمان المكان، كما لعبت دورًا مهمًا في ترسيخ ثقافة مجتمعية جديدة تعتمد على التّكنولوجيا الحديثة والتّقدم الهائل الّذي أحرزته في مجال الاتصال بين الناس، بحيث أصبحت لاعبًا أساسًا ومهمًا، ليس في حياة الأفراد فقط، بل الأمم أيضًا.'),
 ('ص 48', 'نجحت وسائل الاتصال الحديثة، في زمن قياسي، في ترسيخ طرق جديدة للتواصل بين الناس، بحيث باتت طرق التّواصل التّقليدية تعاني التّهميش خاصة بين الأجيال الجديدة، فحظيت وسائل التّواصل الاجتماعي بشعبية عالية في دولة الإمارات العربية المتحدة، وتستخدم على نطاق واسع'),
 ('ص 49', 'سواء من قبل الأفراد، أو من قبل الجهات الحكومية والمؤسسات الخاصة وذلك لأن وسائل الاتصال الاجتماعي الجديدة تعد من وسائل الاتصال السّهلة والمتوافرة في يد كل شخص يدرك أهمية هذا النمط الجديد من التّواصل في خدمة أغراضه الحياتية والاتصال مع الآخرين في زمن باتت فيه وسائل التّواصل التّقليدية بطيئة أو مكلفة في كثير من الأحيان.'),
 ('ص 49', 'وعلى الرّغم من تجذُّر الثّقافة التّقليدية في مجتمع الإمارات، وخاصة بين الأجيال القديمة، فإن وسائل التّواصل الحديثة بدأت تهدد تلك الثّقافة، ولاسيما أنها احتلت فعلًا حيزًا كبيرًا في حياة الأجيال الجديدة تاركة القليل للثقافة المجتمعية التّقليدية لكي تستمر.'),
 ('ص 49', 'ويمكن ملاحظة تأثير وسائل التّواصل الاجتماعي الحديثة في المناسبات الوطنية والاجتماعية وحتى الدّينية كأيام الجمعة وشهر مضان المبارك والأعياد؛ حيث نافست وبقوة وسائل التّواصل التّقليدية، وتغلبت عليها في التّواصل بين الناس وإرسال التّهاني والتّبريكات واستقبال الأخبار. وأمام هذه المنافسة القوية من قبل وسائل التّواصل الجديدة لم يتبق أمام وسائل التّواصل التّقليدية، إلا القليل لكي تقوم به لحماية نفسها.'),
]
O['T1-L18'] += [
 ('ص 50 (أولًا: مفهوم مواقع ووسائل التواصل الاجتماعي)', 'مواقع التّواصل الاجتماعي عبارة عن أدوات تستخدم من خلال أجهزة الحاسوب وهي تمكن المستخدمين من إنشاء ومشاركة وتبادل المعلومات والصّور في شبكات ومجتمعات افتراضية.'),
 ('ص 50', 'وهي أيضًا عبارة عن مواقع على شبكة الإنترنت توفر لمستخدميها فرصة للحوار، وتبادل المعلومات، والآراء والأفكار والمشكلات من خلال الملفات الشّخصية، وألبومات الصّور وغرف الدّردشة وغير ذلك.'),
]
O['T1-L19'] = [
 ('ص 50 (ثانيًا: أهمية وسائل التواصل الاجتماعي)', 'يرى صاحب السمو الشيخ محمد بن راشد آل مكتوم نائب رئيس الدّولة رئيس مجلس الوزراء حاكم دبي -رعاه الله- وسائل التّواصل الاجتماعي بأنها غيّرت مفاهيم، وفتحت أبوابًا، وأسقطت حواجز، وطوّرت العمل، وجعلت الجمهور جزءًا من التّنمية.'),
 ('ص 50', 'حيث تؤدي وسائل التّواصل دورًا كبيرا في حياة المجتمع والناس، بما تمتلكه من ميزات،تغلبت على حدود الزّمان والمكان ورفعت سقف مستوى التّفاعلية التي تعد مؤشرا فعالًا لنجاح العملية الاتصالية ومثلت وسائل التّواصل تطورًا إيجابيًا كبيرًا، وساهمت في نشر الوعي والثّقافة، وشكّلت ما يشبه المنتديات والمحافل الثّقافية، بالإضافة إلى كونها وسائل ترفيهية أيضًا، إضافة إلى أنها باتت منصات إعلانية تجارية، ونوافذ للترويج الإعلاني، إضافة لذلك أن هذه المواقع شكّلت منبرًا من لا منبر له، إلا أن أحدًا لا يمكنه أن ينكر أن بعض الاستخدامات غير السّليمة لهذه الوسائل، شكّلت مخاطر جمة، على المجتمع، لتصبح بسبب سوء استعمال البعض لها سلاحًا ذا حدين.'),
]
O['T1-L20'] = [
 ('ص 51 (ثالثًا: إيجابيات مواقع التواصل الاجتماعي وسلبياتها - 1. الإيجابيات)', 'تتلخص أهم إيجابيات استخدام مواقع التّواصل الاجتماعي بما يأتي: تنمية الذّات وتطويرها وذلك من خلال اكتساب مهارات التّواصل النشط وتحقيق الإبداع في مجالات الحياة من خلال تبادل الخبرات عبر التّواصل الاجتماعي. | متابعة آخر المستجدات العلمية. | توفير الجهد وتكلفة التّواصل مع أصدقاء أو أقارب بعيدين جغرافيا. | تلاقي أصحاب الهوايات وتعرف بعضهم بعضًا وتعزيزها باستمرار. | صقل شخصية الفرد من خلال سعة ثقافته واندماجه مع المحيط الثّقافي إلكترونيًا. | الإسهام في النقد الموجه والبناء والتّأثير في متخذ القرار السّياسي مما يتفق مع المصلحة العامة. | الدّعاية الاقتصادية من خلال نشر الإعلانات الخاصة بأصحابها.'),
 ('ص 51 (2. السلبيات)', 'العبث والفوضى على وسائل التّواصل الاجتماعي تأكل من المنجزات، كما جاء في إحدى الرّسائل الست الّتي ذكرها صاحب السّمو الشيخ محمد بن راشد آل مكتوم نائب رئيس الدّولة رئيس مجلس الوزراء حاكم دبي -رعاه الله- عبر حسابه على تويتر في الأول من سبتمبر 2019م: | تؤثر مواقع التّواصل الاجتماعي في الجانب الأسري حيث يؤدي الدّخول إليها إلى العزلة الاجتماعية وعدم اندماج الفرد مع أسرته، وغيابه وقلة المشاركة في المناسبات الاجتماعية وغير ذلك. | الإساءة إلى الآخرين ونشر الأكاذيب حيث أن معظم المعلومات الّتي تبثها تلك المواقع هي للأسف معلومات غير محققة. | بث الأفكار الهدامة والدّعوات المنحرفة والتّجمعات الفاسدة المفسدة. | عرض المواد غير الأخلاقية الخادشة للحياء.'),
]
O['T1-L20'].append(('ص 52', 'التّشهير والمضايقات والابتزاز والتّزوير. | ضياع وهدر الوقت. | الدّخول الى المواقع غير الأخلاقية الذّي يتعارض مع الضّوابط الدّينية والثّقافية والاجتماعية وأخلاق المجتمع. | الإدمان على الإنترنت، أي الجلوس مطوّلًا على المواقع بعيدًا عن الأجواء الأسرية.'))
O['T1-L21'] = [
 ('ص 52 (رابعًا: المسؤوليات التي يجب إدراكها عند مشاركة المعلومات والمعرفة)', 'عدم نشر المعلومات والأخبار المضللة وغير الصّحيحة. | عدم إطلاق الأحكام على الآخرين من خلال المدونات ومواقع الانترنت والبوابات الاجتماعية لأن هذا من شأنه إثارة المشاعر السّلبية وقد يؤدي لإثارة القلاقل. | التّعامل برفق مع الأشخاص من المجموعات العرقية أو المعتقدات الدّينية المختلفة.'),
 ('ص 52 (الجرائم الإلكترونية)', 'تعرف الجرائم الإلكترونية باسم الجرائم الرّقمية، حيث تشترك هذه المسميات جميعها في أنها تشير إلى الجرائم الّتي ترتكب باستخدام التّقنيات، وهذه الجرائم هي عبارة عن استخدام أجهزة الكمبيوتر لإخافة الناس أو للاحتيال عليهم، أو للاستيلاء على معلوماتهم المهمة.'),
 ('ص 52 (ومن أمثلة الجرائم الإلكترونية)', 'الابتزاز. | التّعدي على حقوق الملكية الفكرية. | قرصنة البرامج. | الوصول غير المصرح به. | التّسلل. | التّعدي.'),
]
O['T1-L22'] = [
 ('ص 53 (خامسًا: رؤية القيادة الحكيمة للشخصية الإماراتية على وسائل التواصل الاجتماعي)', 'صاحب السمو الشيخ محمد بن راشد آل مكتوم، نائب رئيس الدّولة رئيس مجلس الوزراء حاكم دبي -رعاه الله- أعلن: "أمجاد الشّعوب تُبنى بالتّفاؤل والأمل والنظرة الإيجابية للمستقبل المدعومة بالتّخطيط والعمل الجاد لبلوغ الأهداف.. وعليكم مسؤولية كبيرة تجاه مجتمعاتكم وتبني ما يهم الناس ويمس حياتهم اليومية.... نعوّل عليكم لتقديم القدوة والمثل الطّيب في المجتمع كنماذج تحمل مسؤولية التّرويج للفكر المستنير في عصر أصبح طابعه السّرعة والتّغيير".'),
 ('ص 53', 'وأوضح سموه إلى أثر التّواصل كقيمة إنسانية نبيلة أرستها دولة الإمارات ضمن الأسس الّتي ارتكز عليها بناء دولة الاتحاد، وترجمه حكّام دولة الإمارات -حفظهم الله- بصورة عملية سواء عبر مجالسّهم قديمًا ومن خلال شبكات التّواصل في وقتنا الرّاهن، لتستمر دولة الإمارات في تقديم نموذج يحتذى لما يجب أن يكون عليه التّواصل الفعال الذّي يُعَدُّ أساس النّجاح، وهو ما أنعم الله به على مجتمع الإمارات بكل ما يحظى به من تنوع ثقافي كان دائمًا مصدرًا لطاقة إيجابية تدعم مسيرة البناء وتعزز خطواتنا نحو المستقبل.'),
 ('ص 53', 'حرصت دولة الإمارات على الاهتمام بالشّبكة العنكبوتية ومواقع التّواصل، ووضعت القوانين لمكافحة المخالفات أو الجرائم الإلكترونية عبر الشّبكة العنكبوتية بشكل عام أو مواقع التّواصل الاجتماعي خاصة.'),
 ('ص 53', 'وتعد منصات التّواصل الاجتماعي، منصات يوظفها ويستخدمها الجميع من أفراد المجتمع وخاصة الشّباب الّتي يعتبرونها من وسائلهم الحديثة للتعبير عن طموحاتهم، وخدمة القضايا المحورية محل اهتمام المجتمع بما في ذلك مجالات العمل الخيري والإنساني مع الأخذ في الاعتبار تحليهم بالإيجابية، والبعد عن السّلبية. لذا فإن قيّم مجتمعنا تُملي علينا نهجًا وأسلوبًا واضحًا في التّعامل مع شبكات التّواصل الاجتماعي، فكل إنسان يسعى لمحبة وإعجاب الآخرين؛ لكن قيمنا تملي علينا ألا نغرد خارج السّرب، حتى وإن كان على حساب شعبيتنا، لأن الشّهرة والأرقام هي دليل الانتشار لكن التّأثير الحقيقي يأتي بفعل ما يمليه علينا ضميرنا وواجبنا الأخلاقي.'),
 ('ص 53', 'وحدّد صاحب السّمو الشيخ محمد بن راشد آل مكتوم نائب رئيس الدّولة رئيس مجلس الوزراء حاكم دبي -رعاه الله- في تغريدة على حسابه تويتر في أكتوبر 2019، 10 مميزات ينبغي للشخصية الإماراتية أن تتحلى بها على وسائل التّواصل الاجتماعي، وأبرزها:'),
]
O['T1-L22'].append(('ص 54', 'أهم مميزات الشّخصية الإماراتية على مواقع التواصل الاجتماعي أنها شخصية: تمثل صورة زايد وأخلاق زايد في تفاعلها مع الناس. | تعكس الاطلاع والثّقافة والمستوى المتحضر الّذي وصلته الإمارات. | تبتعد عن السّباب والشّتائم وكل ما يخدش الحياء في الحديث. | علمية تستخدم الحجة والمنطق في الحوار. | تقدر الكلمة الطّيبة والصّورة الجميلة والتّفاعل الإيجابي مع الأفكار والثّقافات والمجتمعات. | نافعة للآخرين بالمعلومة وناشرة للأفكار والمبادرات المجتمعية والإنسانية الّتي يزخر بها الوطن. | مندمجة مع محيطها العالمي، تتحدث لغته وتتناول قضاياه وتتفاعل إيجابيًا مع مستقبله. | واثقة من نفسها، تقبل الاختلاف وتبني جسورا مع غيرها من الشّعوب. | تعكس تواضع الإماراتي وطيبه ومحبته للآخرين وانفتاحه على بقية الشّعوب. | تعشق وطنها .. وتفتخر به .. وتضحي من أجله.'))
O['T1-L23'] = [
 ('ص 54 (سادسًا: دور وزارة التربية والتعليم في تحصين الطلبة)', 'تتعاون وزارة التّربية والتّعليم مع العديد من المؤسسات الوطنية والمجتمعية لزيادة وعي الطّلبة بمفهوم الاستخدام الآمن للإنترنت من بينها برنامج خليفة لتمكين الطلاب (أقدر)، والّذي أسهم وبفعالية من خلال العديد من المبادرات الّتي أطلقها في تكريس ممارسات إيجابية وبناءة لدى الطّلبة عند تعاملهم مع الفضاء الإلكتروني الواسع.'),
 ('ص 54', 'حيث أولت الوزارة اهتمامًا خاصًا بتحصين وعي الطّلبة ضد المحتويات الإعلامية الهدامة والسّلبية وإكسابهم مهارات التّحليل الناقد وذلك في ضوء ما يشهده العالم من تنامي ظاهرة العبث عبر مواقع التّواصل الاجتماعي وبث الرّسائل السّلبية والمغرضة والّتي من شأنها أن تنال من رصيد إنجازات البشرية جمعاء وزعزعة استقرار المجتمعات الآمنة، وعملت من خلال العديد من المحاور على تمكين الطلبة من التّعاطي مع المحتويات والرّسائل الّتي تحفل بها مواقع التّواصل الاجتماعي بحرفية عالية من خلال عدة مبادرات أهمها مؤتمر التّربية الإعلامية السّنوي الّذي تنظمه الوزارة بالتّعاون مع العديد من المؤسسات الإعلامية الوطنية وخبراء في'),
 ('ص 55', 'مواقع التّواصل الاجتماعي لتأهيل الطّلبة للتعامل مع الرّسائل والمحتويات المتنوعة الّتي تقدمها تلك المواقع بشكل علمي مدروس ينأى بهم عن ما قد تحمله من مضامين سلبية تنال من وعيهم واستقرار مجتمعهم.'),
 ('ص 55', 'وتسعى أن تكرس في أذهان الطّلبة ممارسات إيجابية لتمكينهم من مواجهة سيل المعلومات المتدفق عبر وسائل التّواصل الاجتماعي وتميز الغث والسّمين منها من خلال تحقيق مفهوم المواطنة الرّقمية لدى الطّلبة.'),
]
O['T1-L24'] = [
 ('ص 55 (سابعًا: تأثير وسائل التواصل الاجتماعي في الثقافة المجتمعية لدولة الإمارات العربية المتحدة)', 'يُعَدُّ صاحب السمو الشيخ محمد بن راشد آل مكتوم، نائب رئيس مجلس الوزراء حاكم دبي -رعاه الله- من أكثر القادة في العالم متابعة وتأثيرًا عبر مواقع التّواصل الاجتماعي، واستقطبت حسابات سموه وفكره القيادي ورؤيته للمستقبل ملايين المتابعين من مختلف أنحاء العالم عبر منصات التّواصل الاجتماعي المختلفة الّتي يعتبرها سموه جسورًا تزيد تقاربه مع الناس وتفاعله معهم بصورة مباشرة، وأنها وسائل للتنمية والمعرفة والابتكار، والاستخدام الإيجابي لها يمكن أن يحرك الشّعوب نحو البناء، ويحرك العقول والقلوب نحو الائتلاف.'),
 ('ص 55', 'ويحرص سموه دائمًا على ترسيخ وسائل التّواصل قوة للخير وأداة للتنمية ومنصة للفكر وبرلمانًا مفتوحًا للجميع، ومنصة دائمة لطرح الأفكار والموضوعات والمبادرات الّتي تنفع الناس وتنشر الخير في المجتمع، إذا يقول سموه: "إن الكثير من المبادرات المجتمعية والإنسانية تم إطلاقها عبر صفحة تويتر، حيث تكللت بالنجاح بسبب التّفاعل الكبير من المتابعين".'),
 ('ص 55', 'وقد نجحت هذه الوسائل القائمة على التّكنولوجيا الحديثة في إحداث نقلة نوعية في حياة الأسرة الإماراتية، حتى التّقليدية منها. فنجد مثلًا، أسرة يعيش أفرادها تحت سقف واحد، وقد يجتمعون على طاولة الطّعام ولكنهم يعيشون أنماطًا اجتماعية وحياتية مختلفة. كما تسببت تلك الوسائل في إضعاف العلاقات الأسرية وفي إحداث عزلة اجتماعية في حياة البشر. ففي كثير من الأحيان مثلًا،'),
]
O['T1-L24'].append(('ص 56', 'نجد مجموعة من الشّباب تجمعهم جلسة واحدة، وكلٌ منهم في عالمه الخاص منشغل بهاتفه.'))
O['T1-L24'] += [
 ('ص 56', 'لقد وضعت وسائل التّواصل الاجتماعي الجديدة كثيرًا من وسائل تواصلنا التّقليدية تحت الاختبار، خرجت منها وسائل التّواصل الجديدة منتصرة بحكم انحياز الأجيال الجديدة لها، وبحكم قدرتها الهائلة على التّواصل السّريع، بل غير الشّابة أيضًا والمقدرة لقيمة الوقت وسرعة إيصال المعلومة في زمن باتت فيه السّرعة قيمة مهمة جدًا.'),
 ('ص 56', 'واليوم تؤدي وسائل التّواصل الجديدة دورًا مهمًا ليس فقط في ترسيخ ثقافة مجتمعية جديدة، بل في ترسيخ ثقافة نفسية وسياسية وإعلامية جديدة في حياة الأفراد أيضًا؛ حيث باتت وسائل الإعلام تعتمد عليها للحصول مثلًا، على معلومة ما أو جس نبض الشّارع، وغيرها من القضايا الّتي باتت تشغل الناس حتى أصبح الجميع غير قادر على الاستغناء عنها. واستطاعت وسائل التّواصل الحديثة وبسرعة إدخال العديد من طرق التّواصل الجديدة في حياة الناس في الإمارات. فكثير من الأسر الإماراتية تواجه، كغيرها من الأسر، ضغوط الحياة العصرية ومسؤولية التّربية وتنشئة الأبناء. فمعظم هذه الأسر تستخدم الهاتف المتحرك والبريد الإلكتروني ووسائل التّواصل الاجتماعي للبقاء على اتصال وتواصل مع أبنائها. فالأطفال اليوم يستقون الكثير من القيم من وسائل أخرى كالتّلفاز والإنترنت ووسائل التّواصل الاجتماعي الحديثة.'),
 ('ص 56', 'لقد تسببت وسائل التّواصل الجديدة في إحداث تغير في أنماط حياة الأفراد وثقافتهم على مختلف أعمارهم. فكثير من أمراض العصر المنتشرة بين الشّباب كالانطوائية والعزلة الاجتماعية وإدمان الإنترنت والفشل الدّراسي واكتساب عادات وقيم سلبية.'),
]
O['T1-L25'] = [
 ('ص 56 (ثامنًا: دور حكومة الإمارات في دعم وسائل التواصل المجتمعي وضبطها)', 'سادت في الفترة الأخيرة ظواهر سلبية تسببت في انفلات وفوضى على مواقع التّواصل الاجتماعي خاصة تويتر، الّذي تحول إلى ساحة للشتائم والكراهية والإساءة إلى رموز الدّول أو استهداف الأشخاص، حيث يتعمد بعض المغردين تصفية حساباتهم الشّخصية عبر منصات افتراضية.'),
 ('ص 56', 'وشجعت حكومة دولة الإمارات العربية المتحدة على التّفاعل مع كل مظاهر التّطور التّكنولوجي'),
 ('ص 57', 'حرصًا منها على أهمية وسائل التّواصل الاجتماعي في التّحولات المستقبلية، لكنها لم تتوانَ في التّصدي بحزم لكل مظاهر الانفلات الّتي تهدد الأمن الوطني من خلال سن مرسوم بقانون اتحادي رقم 5 لسنة 2012 وتعديلاته في شأن مكافحة جرائم تقنية المعلومات تضمن عقوبات تطال من ينشئ أو يدير موقعًا إلكترونيًا أو ينشر معلومات بهدف التّرويج لأفكار من شأنها إثارة الفتنة أو الطّائفية أو الإضرار بالوحدة الوطنية والإخلال بالآداب العامة، وأفرد عقوبات صارمة بحق من يقوم بنشر معلومات أو أخبار أو إشاعات على موقع إلكتروني أو أي شبكة معلوماتية بقصد السّخرية والإضرار بمكانة الدّولة ومؤسساتها.'),
 ('ص 57 (معايير تنظيمية)', '1. تحصين وعي الطّلبة بالفكر النقدي والتّحليلي. | 2. وضع قوانين وتشريعات تنظم المحتوى الرّقمي. | 3. حظر حساب المسيء أو المحكوم عليه بعقوبة جريمة إلكترونية. | 4. التّعديل على قانون مكافحة جرائم تقنية المعلومات. | 5. توعية أفراد المجتمع بمفهوم الاستخدام الآمن للإنترنت. | 6. رخصة للممارسة الإعلامية عبر (التّواصل الاجتماعي). | 7. ترسيخ المسؤولية المجتمعية لتعزيز الحس الوطني. | 8. تعزيز رقابة الأسرة على تصرفات الأبناء في العالم الافتراضي. | 9. الرّقابة الذّاتية عنصر رئيس في الاستخدام الآمن للإنترنت. | 10. التّغريد من أجل الوطن ضمن إطار من المسؤولية يخضع للقوانين. | 11. التّحديث المستمر للمناهج لتعزيز الاستخدام الأمثل للتكنولوجيا. | 12. التّبليغ عن العابثين وعدم التّفاعل مع أي نوع من الشّائعات. | 13. التّعريف بالعقوبات الّتي تتخذها السّلطات بحق العابثين والمسيئين.'),
]
O['T1-L25'] += [
 ('ص 58 (قوانين وسائل التواصل الاجتماعي)', 'القانون الاتحادي رقم (12) لسنة 2016، بتعديل المرسوم بقانون اتحادي رقم (5) لسنة 2012 في شأن مكافحة جرائم تقنية المعلومات.'),
 ('ص 58', 'يُطبق القانون الاتحادي رقم (12) لسنة 2016، بتعديل المرسوم بقانون اتحادي رقم (5) لسنة 2012 في شأن مكافحة جرائم تقنية المعلومات، وغيره من القوانين المتعلقة بحماية الخصوصية، ومنع انتهاك البيانات الشّخصية عند استخدام وسائل التّواصل الاجتماعي.'),
 ('ص 58 (ومن تلك المخالفات)', 'التّقاط صور أو مقاطع فيديو للغير ونشرها من دون موافقتهم. | التّهديد، والابتزاز، والسّب، والقذف، وتشويه سمعة الغير. | تداول الشّائعات أو معلومات غير صحيحة، أو غير دقيقة، أو مضللة. | إرفاق أسماء الأخرين (tag) دون موافقتهم. | استخدام شبكة معلوماتية أو إحدى وسائل تقنية المعلومات في الاعتداء على خصوصية الغير في غير الأحوال المصرح بها قانونًا.'),
 ('ص 58 (قانون مكافحة التمييز والكراهية)', 'في يوليو 2015، أصدر الشيخ خليفة بن زايد آل نهيان رحمه الله- مرسومًا بقانون رقم 2 لسنة 2015 بشأن مكافحة التّمييز والكراهية.'),
 ('ص 58', 'يجرم القانون كل قول أو عمل من شأنه إثارة الفتنة أو النعرات، أو التّمييز بين الأفراد أو الجماعات من خلال نشره على شبكة المعلومات، أو شبكات الاتصالات، أو المواقع الإلكترونية، أو المواد الصّناعية، أو وسائل تقنية المعلومات، أو أية وسيلة من الوسائل المقروءة أو المسموعة أو المرئية، وذلك بمختلف طرق التّعبير كالقول، أو الكتابة، أو الرّسم.'),
]
# ملاحظة: في الدروس الطويلة تُنقل الفقرات الأولى كاملةً حرفيًا (والمولّد يحيل إلى بقية الصفحات).
O['T2-L01'] = [
 ('ص 60 (أولًا: سنع الاستقبال)', 'شكلت تقاليد استقبال الضّيف وإكرامه مظهرًا اجتماعيًا مهمًا في العادات والتّقاليد الخاصة في المجتمع الإماراتي، حيث أسهمت في تمكين أواصر التّعاون والتّرابط الاجتماعي.'),
 ('ص 60', 'ورغم التّطور الحضاري وانتشار أفراد الفريج الواحد في أماكن سكنية متباعدة أحيانًا، نتيجة الازدهار، فقد حافظ مجتمع الإمارات على سلوكه (العادات والتّقاليد والسَّنَعْ)، وفي كل الأحوال بقيت الزّيارات التّقليدية عنوانًا مميزًا للمجتمع الإماراتي.'),
 ('ص 60', 'الجدير بالذّكر أن السَّنَعْ المرتبط بالزّيارة، مرّ بمراحل فرضتها وسائط التّواصل القديمة والحديثة.'),
 ('ص 60', 'فسابقًا كانت الزّيارة تتم دون سابق إعداد أو تحضير، أما الآن فوسائل الاتصال الحديثة وفرّت للزائر والمُزار العلم المسبق بالزّيارة، وما تستوجبه من استعداداتٍ لكلا الطّرفين.'),
 ('ص 60', 'وقديمًا كان البدو يستقبلون ضيوفهم أو زوّارهم فيما يسمى (الحِظِيرة) في فصل الشّتاء وهي بناء مُشاد من أغصان بعض الأشجار والنباتات الصّحراوية مثل: الأرطا، والغاف، والمرخ، على شكل نصف دائرة وبارتفاع متر ونصف، وتحتوي في مكانٍ ما منها على حفرة لإشعال النار وإعداد القهوة العربية، والمعاميل وغير ذلك من مستلزمات الضّيافة كالقدوع (التّمر).'),
 ('ص 60', 'وعادة ما يتم بناء الحظيرة في مكان يتوسط بيوت الفريج الذّي يتكون من 7-8 بيوت شعر، أو خيام في فصل الشّتاء، وتستخدم الحِظِيرة لاستقبال الضّيوف أو الزّوار بكل معاني التّرحاب والسّعادة، سواء كانوا راجلين أو على ظهور مطاياهم، بألفاظ شائعة، مثل: مرحبا السّاع، هذه السّاعة المباركة، زارتنا البركة، حياكم الله، مرحبا ومسهلا، مرحبا من سرتوا إلين ييتوا، مرحبا يالله حيّهم.'),
 ('ص 60', 'والضّيف القادم من خارج الفريج يطلق عليه اسم (خاطر)، والمجموع (خُطّار).'),
 ('ص 61', 'وحال وصول الضّيف إلى الحِظِيرةِ أو السّبلة، تبدأ تقاليد الاحتفاء به، على النحو الآتي: 1. التّرحيب بالضّيف بعبارات متعارف عليها ويرددها الصّغير والكبير عند قدوم الضّيف، ومن أبرزها: مرحبا السّاع - مرحبا بك من سرت إيلين بيت. | 2. يرد الضّيف: "السّلام عليكم ورحمة الله وبركاته، المرحب باقي" أو "المرحب لا هان". | 3. المواﻳﻬﺔ "التّحية بالخشم" بين الضّيف ومستقبليه، وذلك بملامسة الأنف الأنف الآخر مرةً أو مرتين بصورة خفيفة، مع وضع كف صاحب السّلام يده اليمنى على الكتف الأيسر للضّيف (المُسلّم عليه)، وبالعكس.'),
 ('ص 61', 'ومن المعيب أن يُسلم المرء بالخشم دون أن يضع يده على كتف من يُسلم عليه.'),
 ('ص 61', 'والسّلام بالأنف سَنَعْ إماراتي قديم يحمل من المعاني والدّلالات المجتمعيّة الشّيء الكثير، فالأنف بالنسبة للإنسان رمز السّموّ والرّفعة والشّهامة والشّمم، وهو العضو الأبرز في وجه الإنسان ومقدمة ناصيته، لذا كان على الدّوام أعز شيء في جسم الإنسان ووسيلة التّواصل المثلى، والألُفة واللقاء الحميم، به يُشار إلى سمات الرّجولة والوفاء بالعهود، والمناقب الحميدة، فهو الرّابط في المواثيق والعهود بين الأشخاص، يكفي وضع سبابة اليد عليه في حالات القبول والرّضا، والالتزام بتنفيذ أمر أو حاجة معينة.'),
 ('ص 61 (التحفيات)', 'هي سؤال الضّيف عن حاله وحال من يَعزُّ عليه، بعبارات مثل: شحالك والسّلامة؟ الرّد: بخير الله يسلمك. | شحالك والمعونة؟ الرّد: بخير الله يعينك على طاعته. | شحالك، وشحال تواليك؟ الرّد: لا تلّاك بين ولا مكروه.'),
]
O['T2-L01'] += [
 ('ص 62', 'وفي حال كان المستقبلون للضّيف مجموعة، فبعد السّلام عليهم، يتحفاهم وهم واقفون قائلًا: "شحالكم كلٍ بحاله"، فيردون عليه: "بخير الله يعافيك"، ثم يقومون بتقليطه (تقريبه) للجلوس معه.'),
 ('ص 62', 'وهنا لا بدَّ من التّنبيه أن يلتزم كل من في المجلس بالوقوف حتى انتهاء الضّيف من السّلام عليهم جميعًا، وبعد تحفياتهم يقومون بتقليطه. وكل ذلك يشكل جزءًا من تقاليد استقبال الضّيف.'),
 ('ص 62', 'وهنا لابد لصاحب المجلس أو صاحب المكان من أن يُجلس الضّيف على يمينه، كما على الحضور توفير المكان لراعي المجلس وضيفه ليكونا في صدر المجلس احترامًا وتقديرًا لهما.'),
 ('ص 62 (تحضير القهوة - قراءة إثرائية)', 'يتم تحضير القهوة على مشهد من الحضور، وهو إجراء كان متعارف عليه سابقًا، حيث يقوم أحد رجال الحي بالإجراءات والخطوات الآتية: إشعالُ النار (الضّو) في الحفرة المخصصة لها، في الحظيرة. | تحميصُ حبوب البن باستخدام التّاوة والمحماس. | تبريدُ حبوب البن لفترة وجيزة في المبردة. | طحنُ حبوب البن باستخدام المنحاز والرّشاد. | وضعُ البن المطحون في دلة المخمرة، مع الماء النظيف وفق معايير محددة، وغلي المزيج. | تصفيةُ القهوة المغليّة أو المفورّة في دلة الملقمة. | تزويدُ دلة المزلة بالقهوة الصّافية المعدة. | شربُ فنجال الهيف من قِبل معد القهوة للتأكد من جاهزية القهوة للصب. | صب القهوة من دلة المزلة للضّيف والحضور، وذلك بعد تقديم القدوع (التّمر).'),
 ('ص 63 (صب القهوة)', 'الجدير بالذّكر أن صبُّ القهوة، يتم من قبل أصغر الأشخاص، أو من هو مكلّف بذلك، وفق الخطوات الآتية: وقوفُ من يصب القهوة أمام الضّيف باحترام. | إمساكُ دلة القهوة باليد اليسرى، والفناجيل باليد اليمنى. | صبُ القهوة في الفنجال إلى مادون المنتصف (الثّلث). | تقديمُ الفنجال للضيف.'),
 ('ص 63', 'علمًا بأن الفنجال (الفنيال) أربعة أنواع: 1. فنجال الهيف: ويشربه معد القهوة، للتأكد من حسن إعدادها وعدم وجود نواقص ما في تحضيرها. | 2. فنجال الضّيف: وهو الفنجال الأول الّذي يُقدم للضيف تكريمًا لقدومه. | 3. فنجال الكيف: وهو الفنجال الثّاني للضيف للاستمتاع بالقهوة التّي يشربها. | 4. فنجال السّيف: وهو ما يسمى بفنجال (اللزم أو العهد) بين الضّيف والمُضيف، للحماية والمساندة في السّراء والضّراء.'),
 ('ص 63', 'البدء بتقديم فنجال القهوة بأكبر الحاضرين جاهًا أو سنًّا، ومن ثم الّذي يليه من جهة اليمين.. وهكذا.. | هز الفنجان من قبل الشّخص الّذي يتناول القهوة، إشارة إلى أنه اكتفى من شربها، وقول كلمة: "غنيت".'),
]
O['T2-L01'] += [
 ('ص 65 (تقديم العود)', 'يُقدم مرتين، المرة الأولى لدى قدوم الضّيوف، والمرة الثّانية بعد تناولهم الطّعام، وفي الحالتّين يُقدم أولًا للضيف وللشخص الأكبر في المجلس، ثم للجالسّين على يمينه، وهكذا حتى الانتهاء من تقديمه للجميع.'),
 ('ص 65', 'وفي حال عدم وجود شخصية كبيرة في المجلس، يتم تقديم العُودْ بدءًا من يمين المجلس. وفي بعض الأحيان تكون دائرة المدخن غير مكتملة مما يستوجب تقديمه من اليسار إلى اليمين، مع مراعاة أن يكون التّقديم باليد اليمنى في كل حالة.'),
 ('ص 65', 'بقي أن نشير في هذا المجال إلى أن مراسم الضّيافة لا تكتمل إلا بتقديم العُودْ، وهي إشعار للضيف بمغادرة المجلس، عملا بالمثل الشّعبي الدّارج "ما عقب العُودْ قعود".'),
]
O['T2-L02'] = [
 ('ص 65 (ثانيًا: سنع إكرام الضيف)', 'إكرام الضّيف بذبح ذبيحة له، تقديرًا لقدومه إلى الحي أو الفريج، ويقوم بذلك من تقع عليه (النايبة)، الّتي سيُشار إليها لاحقًا.'),
 ('ص 65', 'ومن التّقاليد المجتمعيّة في الماضي الّتي تنم عن تعاضد المجتمع وتآزره في حمل تكاليف الضّيافة، وإكرام الضّيف، ما يلي: (قراءة اثرائية)'),
 ('ص 65 (1. النايبة)', 'صورة من صور التّكافل والتّعاضد الاجتماعي في دولة الإمارات العربية المتحدة، وهي قديمة ومتجذرة في التّراث الإماراتي الأصيل.'),
 ('ص 65', 'ويُقصد بها تناوب أبناء الفريج الواحد في إكرام ضيفهم، فإذا ما تولى أحدهم إكرام الضّيف في هذه المرة، تولى شخص آخر إكرام الضّيف القادم في المرة الثّانية، وهكذا دواليك، ضمن مسؤولية جماعية تنهض بقيم المجتمع وتقاليده، وفي حال أقام الضّيف في الفريج لعدة أيام التزم الجميع بإكرامه.'),
 ('ص 65', 'وهناك أيضًا ما يعرف بنايبة الجدر: وهي تقليد يقوم به الجيران فيما بينهم بالتّناوب لإعداد طعام'),
 ('ص 66', 'الغداء والعشاء بصورة خاصة سواء كان تكريمًا لضيف أو دون ذلك.'),
 ('ص 66 (2. المقصورة)', 'لونٌ آخر من ألوان إكرام الضّيف، إذ يتوجب خلالها على المضيف إكرام ضيفه بصورة خاصة، إذا كان من أقربائه أو تربطه به علاقة خاصة دون أن تسقط عنه واجب النايبة تجاه الفريج، وهذا ما يُلخصه القول: "ميبوعة غير متبوعة" في بعض المناطق بمعنى أن المقصورة حق على هذا الشّخص دون غيره من أبناء الفريج. كونه من أحد أقربائه.'),
 ('ص 66', 'وفي حال وصول الضّيف في وقتٍ متأخر من حلول واجب قرع الجيران، يقوم المعزب بذبح كرامةً لضيفه، دون مشاركة الجيران فيها.'),
 ('ص 66 (3. الدايرة)', 'شكل آخر من السَّنَعِ الإماراتيِّ في إكرام الضّيف، يتلخص في صورتين: الصّورة الأولى: إكرام الضّيف الجار الّذي يشارك في المرعى، والماء، حيث من الواجب على أبناء الفريج إكرامه بالتّناوب، بحيث يحل ضيفًا على كل منهم بالتّناوب بين الجيران، وفي ذلك شعور عال بالمسؤولية تجاه الجار من جهة، وتعميق الصّلة بالجار وحمايته والمحافظة عليه، وعلى ممتلكاته من جهة أخرى.'),
 ('ص 66', 'أما الصّورة الثّانية: فتتمثل بإكرام القادمين من الحج أو العمرة، أو الحضار في محاضر ليوا، والعين في فترة المقيظ، وللحضار سَنَعٌ خاص بالكرم، بحيث يتوجب على أول القادمين إلى المحضر في ليوا أو واحات العين مثلًا، دعوة الحضار الآخرين الّذين يصلون تباعًا بعده إلى هذه الأمكنة، وإكرامهم، ليقوموا بدورهم فيما بعد بالتّناوب فيما بينهم في القيام بواجب الإكرام للآخرين، وهكذا إلى أن تكتمل دائرة التّكريم، وهذا لون آخر في التّكافل الاجتماعي والسَّنَعِ الإماراتيِّ في التّعامل مع الجار وإعانته، والمحافظة عليه وحمل المسؤولية الاجتماعية في العديد من الواجبات.'),
]
O['T2-L02'] += [
 ('ص 67', 'أو دايرة عند جيرانه، أو أحد أصدقائه دون أن يحلف أو يعزم الضّيف والحضور.'),
 ('ص 67', 'وبأقل من ذلك أن يُجامل في العزم والدّعوة لتناول الطّعام في بيته، فليس من السَّنَعْ أو السّلوم أن يغسل يديه بعد الطّعام ويُغادر إلى بيته دون القيام بواجب الدّعوة هذه، وما دام حضر مأدبة إكرام الضّيف من قبل جاره أو أبناء حيه، وجب عليه القيام بالواجب ذاته، وإلزام الضّيف وإكرامه واجب في كل المناسبات الّتي تستوجب ذلك، مثل: الحج، والعمرة، والحضار في ليوا، والعين، وأماكن الاصطياف الأخرى، والدّايرة بين الجيران.'),
 ('ص 67', 'ومن السَّنَعِ الإماراتيِّ أنه إذا دخل رجل على أناس وهم جالسون حول صينية الطّعام في ريوق أوغداء أو عشاء، أن يقول لهم: "هَنَهُمْ"، فيردوا عليه: "وأنت منهم، أقرب"، أي: (تفضل واجلس لتناول الطّعام)، وذلك بدلًا من إلقاء السّلام الّذي يستوجب من الحضور القيام من المائدة والرّد عليه ومواياته.'),
 ('ص 67', 'وهذا يقودنا إلى ذكر أنواع أخرى من مكونات السَّنَعِ الإماراتيِّ في مجال الحفاظ على الجار وإكرامه؛ فبعد العودة من الصّيد سواء أكان صيدًا بحريًا أو صيدًا بريًا، من غير اللائق اجتماعيًا إخفاء ما تم صيده، من طرائد وأسماك وغيرها عن أعين الجيران، إذ لابد من تقاسمها معهم.'),
 ('ص 67', 'ولقد تجاوزت أشكال التّكافل الاجتماعي في مجتمع الإمارات، ألوان السَّنَعْ المشار إليه سابقًا، إذ أصبح إشراك الجار في الكثير من المناسبات جزءًا من التّقاليد والعادات الإماراتية الطّيبة، ومنها على سبيل المثال لا الحصر: دعوة الجار إلى حضور الولائم بأنواعها المختلفة ومنها: العقيقة والنُذر وقدوم الخطار، غيرها، ولقد ذهب السَّنَعُ الإماراتيُّ في مجال التّكافل الاجتماعي مع الجيران إلى تقاسم الكثير من المنافع الخاصة، مثل ما يسمى ب(المنيحة) وهي من فعل منّح أي أعطى، وهو إعطاء أحد الجيران المقتدرين ناقةً إلى جاره المحتاج، كي يستفيد من حليبها غذاء لأهله وأولاده لفترة معينة.'),
 ('ص 67 (تقديم الطعام للضيف)', 'للسَّنَعِ الإماراتيِّ في تقديم الطّعام للضيف تقاليد وآداب، حرص المجتمع على المحافظة عليها ونقلها من الكبار إلى الصّغار، وشكّلت المائدة الإماراتية مناسبة لتأكيد هذه التّقاليد وتعليمها للأبناء والأحفاد، ومن بين هذه التّقاليد: دعوة الضّيوف للجلوس على مائدة الطّعام، سواء أكانت على الأرض، أو على طاولة. بقول: سمّوا. فإذا كانت المائدة على الأرض، اتخذ الجلوسُ حولها هيئةً معينةً تتمثلُ في ثني الرّجل'),
 ('ص 68', 'اليمنى، والجلوس على الرّجل اليسرى، في مواجهة مائدة الطّعام، وفي حال كان عدد الضّيوف المتجمعين حول المائدة كبيرًا، وجب أن يجلسوا على هيئة (جنب وشاكلة)، بحيث تكون اليد اليمنى المقابلة لصينية الطّعام.'),
 ('ص 68', 'احترام الجالسين على مائدة الطّعام من حيث الحركة، والجلوس وقواعد الاداب تجاه الكبار، في حال قدوم شخص ومعه طفل أو ولد. | احترام الجالسين على المائدة من كبار السّن، فلا يسبقهم في تناول الطّعام، ولا ينهض عن الأكل قبلهم. | مراعاة قواعد المائدة، وآداب الأكل، والتّصرف بلباقة، فإذا كان يأكل الأرز (العيش) عليه أن يأكل مما يليه دون التّجوال في الصّحن من اليمين إلى اليسار، وإذا كان يتناول التّمر من المُعيب حذف السّحاح أو التّمر أو الرّطب في الصّحن، ومن ثم يتناول واحدة منها. | عدم مضايقة الجالسين، والجالّس إلى جانبه على وجه التّحديد في الجلوس والحركة. | يجب البدء في تناول الأرز لقمة أو لقمتين، ومن ثم يمد يده على الودام سواء أكان لحم أو غيره. | عدم العبث بالطّعام، ومراعاة من سيتناوله من المهّال، إذ من غير المناسب أن تكون صينية الطّعام غير مرتبة وقابلة للأكل للذين سيتناوبون على الطّعام لاحقًا، وهذا ما يُلخصه المثل المحلّي: "العيش بالقص، والتّمر بالخص".'),
 ('ص 68', 'ومعنى ذلك أن تخص التّمر بعينيك، وتختار الّذي يناسبك منه، دون أن تحرك ما فيه بإصبعك يمينًا يسارًا، وتأخذ حبة فيما بعد، مع مراعاة ألا تلفظ النوى أمام الحضور، ومن غير اللائق تناول التّمر والقهوة معًا، أيضًا.'),
 ('ص 68', 'كذلك العيش (الأرز) بالقص أي تتناول منه ما هو أمامك دون الانتقال إلى مكان آخر في الصّحن، ودون إزعاج للآخرين الّذين يشاركونك تناوله.'),
]
O['T2-L02'] += [
 ('ص 69', 'ومن المتعارف عليه في السَّنَعِ الإماراتيِّ المرتبط بالكرم، أنه في حال مرور ضيف على بيت أومزرعة أو عزبة، ولم يتم إكرامه في المجلس حسب الأصول المتبعة لأنه على عجلة من أمره، فعلى المضيف (صاحب المزرعة أو المكان) إكرامه على عجل بوضع كرامته (ذبيحته) حيّة في سيارته، والاعتذار منه بأن قدره أكبر من ذلك.'),
 ('ص 69', 'تقديم عبارات الشّكر والامتنان بعد تناول الطّعام، من مثل: أكرمكم الله - جعلها نعمة دايمة وحفظها الله من الزّوال - بيت معمور وحال مستور - كثر خيرك - الله ينعم عليك.'),
]
O['T2-L03'] = [
 ('ص 69 (ثالثًا: سنع توديع الضيف)', 'توديع الضّيوف، وآداب مغادرة المجلس: لا تقتصر الحفاوة بالضّيف على مراسم استقباله المُشار إليها سابقًا، بل لابد من توديعه بالحفاوة والبشاشة والتّرحيب الّتي استقبل بها، وذلك تعزيزًا للنتائج الإيجابية الّتي أفضت إليها الزّيارة، والانطلاق منها إلى زيارات مستقبليّة.'),
 ('ص 69', 'ومن التّقاليد المرتبطة بتوديع الضّيف في السَّنَعِ الإماراتيِّ: تقديم العود للضيف قبل مغادرته المجلس، وهذا يتم باستخدام المدخن الّذي يمرره أحد أبناء صاحب المجلس على الضّيوف، بادئًا بأكبرهم سنًا ومكانة. وهذا هو التّقديم الثّاني للعود.'),
 ('ص 69', 'الاستئذان من صاحب المجلس أو المكان بالمغادرة بكلمات من مثل: ارخصونا - بترخص منكم - بنترخص - من رخصتكم، أكرمكم الله وغناكم أو أكرمتم ودمتم، إذ من السَّنَعِ الإماراتيِّ مغادرة المجلس بعد الوليمة أو بعد فترة وجيزة من تقديمها. | تقديم عبارات الثّناء والشّكر لصاحب المجلس مثل: أكرمكم الله - بيّض الله ويوهكم - أنعم الله عليكم - قصر الشّر عنكم - بيت عامر - بيت معمور وحالٍ مستور. | توديع الضّيف أو الضّيوف إلى باب المنزل من قِبل المضيف، أو إلى السّيارة، وذلك حسب مكانته وقدره وسنه، مستتبعًا بكلمات طيبة مثل: حفظكم الله - لا تقطعونا بزيارتكم - في داعة الله - في أمان الله - في حفظ الرّحمن - حفتكم السّلامة - لا تحرمنا من وصلك.'),
]
O['T2-L04'] = [
 ('ص 72 (أولًا: المجلس الإماراتي أيقونة الترحاب ومرآة السنع)', 'إن تقاليد السَّنَعْ الإماراتية الّتي انتقلت من جيل إلى جيل، والّتي نريد قيادة وشعبًا الاحتفاظ بها كعلامة فارقة تزين ما نقدمه كإماراتيين إلى العالم، وتُعبّر عن روحنا المعطاءة الوثّابة إلى التّناغم مع الآخر، مُرحبّة به بكل أريحية وسعة صدر، تُجسّد التّسامح الفطري الّذي نشأ عليه أبناء الإمارات، وتُعمّقُ جذور تراثهم الأصيل.'),
 ('ص 72', 'وهذه التّقاليد امتداد لموروث عربي امتد عبر صحاري وتلال وسواحل وجبال الوطن، الّتي استقر وارتحل عبر أرجائها الآباء والأجداد، ولقد تميز ذلك الموروث بثقافة قائمة على المشاركة والتّلاحم، أبوية الطّابع تتسع لكل ما يعتري الإنسان من متغيرات صعودا وهبوطا، تلك الثّقافة، الّتي تأصلت في المجتمع نتيجة الظّروف وحياة القبائل القائمة على الحل والتّرحال، والتّنقل طلبًا للكلأ والماء، والّتي في مجملها عززت قيم التّرحاب والضّيافة وحسن الاستقبال. علاوة على أن الآباء والأجداد عاشوا في مجتمع متكافل بالفطرة يهتم فيه الكبير بالصّغير، ويتضامن فيه الغني مع الفقير، مجتمع متلاحم لا مكان فيه للتفرد بالرّأي، والانفصام عن الجماعة.'),
 ('ص 72', 'ولم يزل مجتمعنا الإماراتي متمتعا بنمط تواصل يتميز بأبواب مشرعة دائما تساعد أفراد المجتمع على التّواصل فيما بينهم، والتّكافل في كل ما يتصل بحياتهم، مجتمع يتبارى فيه الحاكم وأبناء المجتمع في إبراز ما هو نبيل من أخلاق وقيم وفضائل إنسانية تجاه القريب والبعيد.'),
 ('ص 72', 'فالاحتفاء بالضّيف سَنَعْ إماراتي أصيل، تتجلى فيه معاني الضّيافة وحسن الاستقبال والتّرحاب، وهو سَنَعْ تمثّله القائد المؤسس الشّيخ زايد بن سلطان آل نهيان -طيب الله ثراه- في مجالسه، فأصبح نمطًا للحياة، ومعيارًا للكرم، ونهجا للتكافل والتّضامن، تتوارثه الأجيال ويعتز به أبناء الإمارات في كل مكان.'),
 ('ص 72', 'لقد بات المجلس الإماراتي وسيلة من وسائل التّواصل والتّفاعل والتّلاحم الفريد بين أبناء المجتمع، ولطالما أعجب القريب والبعيد بالسَّنَعْ السّائد في مجالسّنا، إذ أصبحت المجالّس بحق (مدارس)،'),
 ('ص 73', 'خطوة مباركة ورشيدة من قبل القيادة الحكيمة في دولة الإمارات العربية المتحدة على تعزيز دور المجلس، ورسالتّه السّامية، كمدرسة لتعليم الأخلاق وتعليم السَّنَعْ، والأخذ بقيم المجتمع، من حالة الأقوال إلى حالة الأفعال والسّلوكيات، فوجهت بناء المجالّس وإعمارها في المدن والقرى والأحياء.'),
 ('ص 73', 'باتت هذه المجالّس ملتقى بين مختلف مكونات المجتمع، للتدارس في القضايا الّتي تهم الجميع، وفي تبادل الآراء والأفكار، وتعزيز التّواصل بين الجميع، فأنت تسمع في هذه المجالّس المحاضرات القيمة، واللقاء بكبار المسؤولين، بل يمتد أثر المجلس في الكثير من الأحيان إلى اتخاذ قرارات على مستوى هذه الأحياء، تعود بالنفع والفائدة على الجميع.'),
 ('ص 73', 'ولأن لكل ثقافة ومجتمع أيقونته الدّالة على قيمه العليا والمعبرة عن تميزه الثّقافي وما يقدمه لمن يفد إليه، فإن المجلس الإماراتي هو الأيقونة الأكثر جمعًا والعلامة الأكثر تميزًا في المشهد الاجتماعي الإماراتي عبر الأجيال، من هنا جاء «تسجيل المجالس في القائمة التّمثيلية للتراث الثّقافي غير المادي في منظمة (اليونسكو) إنجازًا مميزًا لإبراز أهمية هذه المجالس، ومكانتها في مجتمع الإمارات، إضافة إلى تعريف المجتمعات الأخرى بالطّابع المميز لهذه المجالس، والّتي يكاد مجتمع الإمارات يتفرد بها بالنسبة للكثير من المجتمعات في العالم».'),
]
O['T2-L04'] += [
 ('ص 74 (المجلس)', 'المجلس اصطلاحًا: نمط مميز للتواصل المجتمعي، ذو طابع مفتوح ينعقد بين عدد من الجالسين، باستضافة فردية أو مشتركة، وقد اشتق لفظ المجلس من الجلوس ليدل على أي ملتقى يجلس فيه الناس مع بعضهم البعض، سواءً أكان الملتقى رسميًا، أم بمناسبة ما، أم عاديًا غير رسمي كمجالّس العائلات والأصدقاء.'),
 ('ص 74', 'إن مفهوم المجلس يتجاوز الدّلالة المادية له من حيث المبنى والتّجهيزات، إلى الدّلالة المعنوية الّتي ميزت مكانته في توفير التّواصل بين أفراد المجتمع، وتبادل الخبرات والمعارف والقضايا المجتمعية، إضافة إلى اكتساب الكثير من التّقاليد والسَّنَعْ كأدب الحوار، والإنصات، وإبداء الرّأي، والجلوس، واستقبال الزّائر، وغير ذلك من أشكال السَّنَعْ الأصيل، الّذي تتكفل المجالّس في نقله إلى زوارها، والوافدين إليها.'),
]
O['T2-L05'] = [
 ('ص 74 (ثانيًا: خصائص المجلس الإماراتي - 1. وسيلة للتلاحم الاجتماعي)', 'أدت المجالّس دورًا مهمًا في تعزيز أواصر التّواصل والتّلاحم بين أفراد المجتمع، وفي حل الكثير من القضايا الطّارئة، إضافة إلى إنعاش الحياة الاجتماعية بشكل كبير، فكانت أشبه ما تكون بالبرلمانات الحديثة، لذلك فإن الحوار الّذي يدور فيها يأخذ طابع الصّدق والصّراحة والحرية الكاملة دون تكلف، وهي ليست مقتصرة على أناس بذاتهم وإنما هي عامة لجميع أفراد المجتمع وطبقاته، وهذه المجالّس منتشرة في مختلف "الفرجان" أي الأحياء، ولم يكن مجلس "الفريج" خاص بأبناء الفريج فقط لكنه مفتوح للجميع.'),
 ('ص 74', 'ويوصف المجلس بأنه قلب التّلاحم، يتم فيه مناقشة القضايا المجتمعية بمختلف مستوياتها بدءًا من الأمور اليومية العادية، ومرورًا بالقضايا ذات الطّابع العائلي والقبلي والمهني والعلمي والثّقافي.'),
 ('ص 74', 'وعلى امتداد أنماط الحياة المختلفة الّتي وجدت على أرض الإمارات، من البداوة المرتحلة عبر الصّحراء إلى أهل السّاحل والمقيمين في المدن والقرى والجبال، وحتى على متن سفن الغوص وتجارة اللؤلؤ فإن الضّيوف القادمين لم يجدوا صعوبة في الدّخول إلى المجالّس المفتوحة، والّتي كان أصحابها في كثير من الأحيان، يترقبون القادمين من رحلاتهم، موفرين لهم كل أشكال الضّيافة والتّرحاب.'),
]
O['T2-L06'] = [
 ('ص 78 (الجزء المقروء من الصفحة)', 'وكانت هذه المساهمات وخاصة المالية منها تسمى (الشوفة) لأن المساهمين كانوا يشاركون بما يشوفونه كمساهمات تعاونية مالية لخدمة المصلحة العامة للبلاد، وكانت هذه المناسبة شكلًا من أشكال التكافل والمسؤولية الاجتماعية التي تميز بها المجلس الإماراتي قديمًا.'),
 ('ص 78', 'إن هذا الشعور العميق بالأمان الاجتماعي، والقدرة الفائقة على إدارة الشؤون من خلال المجالس، لهو شعور مفعم بالإحساس بالآخر، ومصدر من مصادر الثقة: السمة المميزة للإمارات التي تتربع على عرش المؤشر العالمي للثقة بالحكومات، وهي دالة حقيقية على عمق الترابط وإحساس كل فرد في المجتمع بسلاسة الوصول إلى أي مسؤول، وأنه لن يضيع حق ولن تنوب نائبة، ولن يظلم فرد مادامت مجالسنا عامرة وأبوابنا مفتوحة.'),
]
O['T2-L07'] = [
 ('ص 84 (رابعًا: سنع الحديث والإنصات)', 'الإنصات لحديث المتكلم، من آداب السنع الأساسية، وهي مهارة تسهم في التواصل مع الآخرين، فمن السنع أن ينصت الشخص عندما يتكلم الأب أو الضيف، أو الأكبر سنًا، وكم من مرة أسهم الإنصات الحسن في استيعاب الموضوع المطروح، وإيجاد حلول مناسبة له.'),
 ('ص 84', 'والإنصات لحديث المتحدث يتطلب مهارات فرعية من اللازم إتقانها بالنسبة للمتحدث، والمستمع على حد سواء، ومنها معرفة المتحدث متى يتحدث، ومتى ينتهي حديثه، ومعرفة المستمع متى ينصت، ومتى يعرض وجهة نظره.'),
 ('ص 84', 'وقد توارث أبناء الإمارات تلك المهارات، ومنها: الهدوء أثناء الحديث وعدم رفع الصوت، وهذه المهارات في الحديث يطلق عليها في اللهجة الإماراتية (رمسة)، إذ تشير إلى تقصير الدوب بين المتحدث والسامع أو السامعين في أمور شتى، فكثيرًا ما يقول أحدهم للآخر: "مُرْ علينا نقصر الدوب وياك"، أي نتحدث معًا، ونختصر الوقت.'),
 ('ص 84', 'ومن المعيب في السنع الإماراتي مقاطعة المتحدث، وعدم الإنصات إليه.'),
 ('ص 84', 'ومما لا شك فيه أن المجالس بأنواعها المختلفة تلعب دورًا مهمًا في تربية المجتمع على هذا المذهب، انطلاقًا من كون «المجالس مدارس».'),
 ('ص 84', 'ومن واجبات المنصت إظهار اهتمامه للمتحدث، وعدم الانشغال في أعمال وسلوكات جانبية، كالضحك واستخدام وسائل التواصل الحديثة، وعدم مشاركة الآخرين في المجالس بأنواعها فيما يتحدثون به، وفي معالجة القضايا المجتمعية، وغيرها التي يتناولونها في تلك المجالس.'),
 ('ص 84 (ومن أبرز تقاليد المجلس)', 'خلع الحذاء قبل الدخول. | مراعاة آداب الجلوس في المجلس. | الوقوف في كل مرة يدخل فيها شخص جديد، لاستقباله بالسلام والحفاوة والترحيب. | عدم الاتكاء أثناء الجلوس. | عدم الضحك أثناء قدوم أحد الأشخاص إلى المجلس، أو أثناء خروجه. | عدم السخرية والاستهزاء بالآخرين.'),
]
O['T2-L08'] = [
 ('ص 86 (المحور الثامن: سنع الزيارة)', 'تميز المجتمع الإماراتي بتعزيز التواصل بين أفراده، من خلال أنواع كثيرة من الزيارات، وهذا نابع بالأساس من وحدة المجتمع وتجانسه، وصلات القربى والرحم، التي تجمع الأسر الإماراتية على امتداد الرقعة الجغرافية لدولة الإمارات العربية المتحدة.'),
 ('ص 86', 'ومما يبرز مكانة الزيارات في السنع الإماراتي، تعدد أنواعها ومناسباتها وأوقاتها، وآثارها الاجتماعية الجمة. علمًا بأن هذه الزيارات متبادلة على صعيد الأفراد، والأسر، والحكام، وفئات المجتمع كافة، وترتقي بمستوياتها من الزيارات العامة بين أفراد المجتمع، والزيارات الخاصة المتبادلة بين الحكام والمسؤولين من جهة، وأبناء المجتمع من جهة أخرى.'),
 ('ص 86', 'وسنتناول أنواع هذه الزيارات، والسنع الإماراتي المتبع فيها، وفق التصنيف الآتي، مع الإشارة إلى حرص الآباء والأجداد على استدامة هذا الترابط الاجتماعي، والذي يعزز باستمرار لحمة المجتمع وترابطه، ووقوفه صفًا واحدًا في السراء والضراء.'),
 ('ص 86 (أولًا: الزيارات المرتبطة بشخصية الزائر، ومن بينها)', 'زيارات الحكام والشيوخ. | زيارات الحكام والشيوخ للمواطنين. | زيارات المواطنين للحكام والشيوخ. | سنع مراجعة الدوائر والمؤسسات الحكومية. | زيارات الأقارب والأهل. | زيارات الجيران. | زيارات الخطار.'),
 ('ص 86 (ثانيًا: الزيارات المرتبطة بموضوع الزيارة، ومن أمثلتها)', 'زيارة المريض. | زيارة الحاج والمعتمر. | زيارة الأعراس. | واجب العزاء.'),
 ('ص 87 (الجزء المقروء من الصفحة)', 'كثيرًا ما شكل هذا التقليد والتزام أصحاب السمو الشيوخ به أنموذجًا لبقية المسؤولين في مفاصل الدولة، لتطبيقه والسير على هداه، ومؤشرًا لما يجب أن تكون عليه العلاقة بينهم وبين الشعب، وما من شك في أن زيارات الشيوخ لإخوتهم من أبناء الإمارات والمقيمين، تستوجب سنعًا معينًا في استقبالهم وتوديعهم.'),
 ('ص 87', 'ففي زيارة الأعراس مثلًا يستقبل الشيخ من قبل والد العريس، والعريس، ومن يتم اختيارهم من قبل والد العريس ليكونوا من بين المستقبلين، وذلك بغرض تنظيم الزيارة، ومراعاة الوقت المخصص لها من قبل الشيخ، وبعد استقباله في المكان المحدد، تتم مرافقته (تقليطه) إلى المكان المعد لجلوسه، ومن ثم تقديم القهوة العربية والفوالة، وكافة أشكال الضيافة الأخرى له، ومثلما يستقبل الشيخ يودع بالحفاوة والعرفان لهذه الزيارة الكريمة.'),
]
O['T2-L08'] += [
 ('ص 88 (2. زيارات الحكام والشيوخ للمواطنين)', 'لا تنحصر زيارات الشيوخ للمواطنين على زيارات الأفراح والأتراح، بل هناك زيارات خاصة لهم يحظى بها المواطنون بين فترة وأخرى، وهذه الزيارات هادفة وذات معانٍ مجتمعية كثيرة، من أهمها التعرف إلى حالة المجتمع عن قرب، وتوطيد عرى التواصل والمحبة والإخاء مع أبنائه كافة.'),
 ('ص 88 (ومن السنع المرتبط بمثل هذه الزيارات)', 'مراعاة وقت الشيخ المخصص للزيارة. | استقبال الشيخ والترحيب به. | تقديم المستقبلين للشيخ، من قبل المضيف، والتعريف بهم. | تقليط الشيخ للجلوس في صدر المجلس. | تقديم العود، في الأفراح والزيارات الخاصة. | تقديم القهوة له ولمرافقيه. | تقديم الفوالة، أو الكرامة المناسبة إذا كانت الزيارة في فترة الغداء أو العشاء. | تحديد الأشخاص المشاركين للشيخ في الكرامة في الغداء أو العشاء. | عودة الشيخ إلى مكانه في المجلس بعد تناوله وجبة الغداء أو العشاء المعدة له في غرفة الطعام. | تقديم القهوة للشيخ مجددًا، إضافة للعود. | توديع الشيخ في حال طلب من مضيفيه مغادرة المجلس، وذلك بالحفاوة والترحاب الذي استقبل به.'),
]
O['T2-L08'] += [
 ('ص 94 (من تقاليد الزيارة)', 'فيرد عليه متلقي الهدية بعبارات من مثل: بيض الله وجهك - ما قصرت - قصر الشر عنك - جعلها من زود - يعله بيت عامر، جعله على طولة عمرك - الله لا يقطعنا وصلك - جعله (يعله) كل حول دايم.'),
 ('ص 94', 'ومن التقاليد المتعارف عليها في مجتمع الإمارات أنه في حال عودة المسافر إلى أهله، فإنه يجلب معه هدية (صوغة) يخص بها زوجته أو أمه أو أخته، والشفايا التي يوزعها على الأطفال، كأن تكون ألعابًا أو قطعًا من الحلوى.'),
 ('ص 94', 'عدم مغادرة الضيف لبيت مضيفه، إلا بعد الحصول على إذن مغادرته من صاحب البيت، حيث يعد ذلك من آداب السنع والسلوك الاجتماعي.'),
 ('ص 94 (الرفجة)', 'الرفجة: حلف وتأكيد والتزام بقضاء أمر ما، واتمامه بأن يرفج بشخص عزيز على قلبه، كأن تقول ورفجة فلان.'),
 ('ص 94', 'عدم سؤال الضيف عن حاجته إلا بعد مرور 3 أيام على قدومه، إلا إذا بادر هو وأخذه «نيوه» بمعنى أن يعلمك عن حاجته دون علم الآخرين.'),
 ('ص 94', '«نيوه»: حديث خاص بين المعزب (صاحب البيت) والضيف، في حال عدم رغبة الضيف بالإفصاح عن حاجته أمام الحضور في المجلس، والقصد من ذلك عدم إحراج الضيف إذا كان لديه أي مطالب خاصة.'),
]
O['T2-L09'] = [
 ('ص 94 (7. سنع مراجعة الدوائر الحكومية والمؤسسات)', 'من آداب زيارة المراجع لدائرة أو مؤسسة حكومية لغرض ما، الأخذ بخطوات السنع الآتية:'),
 ('ص 94', 'إلقاء السلام على المسؤول والجالسين. | رد المسؤول أيًّا كان على السلام، والوقوف احترامًا للمراجع أو الزائر، سواء ذكرًا كان أم أنثى، باعتبار المسؤول يمثل الحكومة. | تفهم المسؤول لقضية الزائر أو المراجع، وإيجاد حلول لها. | عدم التذمر من الزائر أو المراجع، والانطلاق من المسؤولية والواجب في خدمة المجتمع. | مراعاة الزائر أو المراجع آداب الحديث والحوار واحترام المكان. | على المسؤول إظهار احترامه للمراجعين وتفهم قضاياهم، وإيجاد الحلول المباشرة لها دون تسويف.'),
 ('ص 95 (الجزء المقروء)', 'ومن الضرورة التنبيه إلى أنه في زيارة المريض في بيته، سواء أكان في علاج داخل الدولة أم خارجها، يتعين على الزائر حمل ما يسمى بالكرامة له كما ورد في سنع الزيارة بشكل عام. من العبارات التي تقال في عيادة المريض: الله يشفيك. | ما عليك شر. | ما تشوف إلا الخير. | الحمدلله صحتك زينة.'),
]
O['T2-L10'] = [
 ('ص 102 (المحور التاسع: أم الإمارات)', 'جاء إطلاق اسم أم الإمارات على سمو الشيخة فاطمة بنت مبارك تكريمًا ووفاءً للمرأة الإماراتية التي وقفت إلى جانب مؤسس وباني دولة الإمارات العربية المتحدة، الشيخ زايد بن سلطان آل نهيان -طيب الله ثراه، وعرفانًا جميلًا بالدور الكبير الذي قامت به، ولا تزال في نهضة وتطور الإمارات.'),
 ('ص 102', 'وحصر هذه الجهود وتحديدها يصب في ما نرمي إليه من إبراز دور المرأة الإماراتية في مسيرة التطور والازدهار، والتي تتبوأ فيها سمو الشيخة فاطمة بنت مبارك -حفظها الله- مكان الصدارة والريادة والقدوة لكل نساء الوطن، والنساء في العالم عمومًا، ومن أبرز هذه الجهود:'),
]
O['T2-L11'] = [
 ('ص 102 (أولًا: أم الإمارات وبناء الأسرة الإماراتية)', 'فهي الأم التي أفاضت بكل عواطف وأحاسيس ومشاعر الأمومة على كل أبناء الإمارات، وحرصت على بناء الأسرة الإماراتية وإعطائها الأولوية والصدارة في كل مشروع تنموي، تقول -حفظها الله: "تأتي الأسرة الإماراتية، وابن الإمارات على رأس قائمة أولويات الحكومة، وفي عمق سياساتها الرامية إلى الاهتمام بالإنسان، والحرص على سعادته وتشجيع مبادراته، وتحقيق طموحاته كافة، لذا فلا غرابة أن يحصد شعب الإمارات لقب أسعد شعب في قائمة التقدير الدولي".'),
 ('ص 102 (ثانيًا: أم الإمارات والمرأة العربية)', 'لم يقتصر دور أم الإمارات على الإسهام في قيادة شعب الإمارات، وصون إنجازاته الحضارية والثقافية، بل كان لها دور ريادي بارز في قيادة العمل النسوي على مستوى الوطن العربي، ولقد قرنت دعوتها للنهوض بواقع المرأة العربية بتقديم كل أشكال الدعم المادية والمعنوية، وكان حضورها في المؤتمرات واللقاءات النسوية العربية دعمًا لحقوق المرأة العربية، وتعزيزًا للإنجازات التي حققتها، وها هي تؤكد -حفظها الله- على دور الأسرة العربية في بناء المجتمع بقولها: "إن استقرار الأسرة العربية ونشر السلام بدلًا من العنف والفوضى، وأن تعميق أواصر التعاون بين الشعوب يبدأ من الأسرة التي هي اللبنة الأولى للمجتمع، وبناء الدول والإنسان الصالح فيها".'),
]
O['T2-L12'] = [
 ('ص 103 (ثالثًا: أم الإمارات وثقتها بقدرات المرأة الإماراتية)', 'لم تدخر سمو الشيخة فاطمة بنت مبارك (أم الإمارات) -حفظها الله- جهدًا للأخذ بيد المرأة الإماراتية، والإشادة بقدراتها ومواهبها، وإنجازاتها، ودورها المتميز في بناء المجتمع، حيث تقول: "إن المرأة الإماراتية أثبتت أن لديها كافة المقومات اللازمة التي تمكنها من خوض معترك العمل السياسي والدبلوماسي باقتدار، وإن التجربة قد أثبتت أن تعزيز المشاركة السياسية للمرأة يجب أن يمر عبر رؤية مجتمعية منصفة لقدراتها".'),
]
O['T2-L13'] = [
 ('ص 103 (رابعًا: أم الإمارات والسنع الإماراتي الأصيل)', 'حافظت (أم الإمارات) خلال مسيرتها الطويلة، على العادات والتقاليد التي تعد أنموذجًا يحتذى به من قبل نساء الإمارات في هذا المجال. إذ حرصت في مجالسها، وندواتها، والمؤتمرات التي تقيمها أو تدعى إليها، وفي لقاءاتها مع زوجات الحكام والسلك الدبلوماسي على زيها الإماراتي، وعلى واجبات الضيافة والتكريم والحفاوة، والترحاب، التي عرف بها مجتمع الإمارات منذ القدم.'),
 ('ص 103', 'عززت -حفظها الله- مكانة المجلس واستدامته وفق الدور والمهام التي رسمها القائد والمؤسس الشيخ زايد بن سلطان آل نهيان -طيب الله ثراه- للمجلس، فكان لها ولا يزال مجلسها الخاص الذي تؤمه النساء من كل أنحاء دولة الإمارات العربية المتحدة، وخارجها، يرصد واقع المرأة الإماراتية، وسبل الارتقاء بدورها الفعال في التنمية المستدامة، مقدرة دائمًا هذا الدور المنجز والمنتظر للمرأة الإماراتية، وهنا تقول: "إن التنمية بمعناها الحقيقي، هي النهوض بالمجتمع عن طريق الإنتاج، وعدالة التوزيع، وتحقيق ذلك يتطلب ضمان المساواة بين المرأة والرجل".'),
 ('ص 103', 'أسهم (مجلس أم الإمارات) في حل الكثير من المعوقات والمشكلات الاجتماعية التي تواجه المرأة والأسرة الإماراتية على وجه الخصوص، وهذا الدور لمجلسها العامر، دور مستدام لمجلس الباني المؤسس، ومجالس أبنائه أصحاب السمو الشيوخ.'),
]
O['T2-L14'] = [
 ('ص 104 (خامسًا: أم الإمارات والتراث)', 'عرف عن سمو الشيخة فاطمة بنت مبارك (أم الإمارات) -حفظها الله- أنها من أشد المهتمين بالتراث الوطني الأصيل، والداعين إلى استدامته والمحافظة عليه كداعم أساسي لمسيرة النماء والتطور، وهنا يبرز دورها اللا محدود في دعم جهود المرأة الإماراتية من خلال الاتحاد النسائي العام، وفروعه المنتشرة في كل أنحاء الإمارات، وتمكينها من المهارات، والعادات، والقيم التي تشكل محتوى التراث، وممارساته. وهنا لابد من إبراز دعمها المميز للأسر المنتجة باعتبارها الحاضنة الأساسية للمحافظة على التراث، ودعمها المستمر للمرأة من خلال الفعاليات والأنشطة الثقافية والتراثية كي تطور من إسهاماتها في صون التراث ونقله لأجيال المستقبل.'),
 ('ص 104', 'وهنا تؤكد على دور المرأة الإماراتية في تطبيق وممارسة كل مجالات التراث، وترسيخها، كقيم ثابتة ومهمة، في نفوس الأبناء والأحفاد، تقول أم الإمارات في العمل التطوعي ودور المرأة فيه: "إن نظرتنا إلى العمل التطوعي، أنه ممارسة إنسانية راقية تجسد نهجًا وسلوكًا حضاريًا، يعبر عن رقي الأمم والشعوب، لما يمثله من رمز للتآخي والتآزر والتعاون، ولارتباطه الوثيق وتعبيره الصادق عن أرفع معاني وقيم الخير والإنسانية".'),
]

PARTIAL = {'T2-L01','T2-L04','T2-L05','T2-L06','T2-L08','T2-L09','T2-L15'}
O['T3-L01'] = [
 ('ص 112 (المحور الحادي عشر: السنع في اللباس الإماراتي)', 'تميز أبناء الإمارات بزيهم التقليدي والمتوارث عبر الأجيال، إذ لا يزال الرجال والنساء محافظين على زيهم الوطني في شتى المناسبات.'),
 ('ص 112', 'واللباس الإماراتي من بين ألبسة الشعوب المتوائمة مع بيئاتها، إذ يعكس أشكال التكيف مع البيئة الصحراوية التي تتميز بارتفاع درجة الحرارة والجفاف والرطوبة في بعض الأماكن.'),
 ('ص 112', 'والسنع الإماراتي المرتبط باللباس يتمثل بحرص الآباء والأمهات على التزام أبنائهم باللباس الوطني المعروف، إذ ترى الطفل الصغير يلبس العقال والغترة والكندورة سيرًا على نهج أخوته ووالده والكبار.'),
 ('ص 112', 'ويمكن أن نقسم اللباس الإماراتي التقليدي إلى قسمين أساسيين، هما:'),
 ('ص 112 (أولًا: مكونات لباس الرجل الإماراتي)', 'القحفية: (الطاقية) تستخدم لتثبيت الغترة والعقال على الرأس. | العقال: مصنوع من الصوف ويوضع على الرأس فوق الغترة. | الغترة: قطعة من القماش الأبيض الناعم توضع فوق القحفية وتثبت بالعقال، وفي حال عدم استخدام العقال، تلف الغترة على الرأس بما يعرف بالحمدانية أو العصامة، أو المكورة. | الكندورة: ثوب من القماش الأبيض يرتديه الرجال داخل البيت وخارجه، وفي الشتاء يصنع الثوب من قماش أكثر سماكة وألوانه متعددة. | الوزار: قطعة من القماش الأبيض تلف على النصف السفلي من الجسم. | البشت: عباءة تصنع من الصوف بألوان مختلفة، وتلبس فوق الكندورة في بعض المناسبات.'),
]
O['T3-L02'] = [
 ('ص 113 (ثانيًا: مكونات لباس المرأة الإماراتية)', 'الشيلة: غطاء للرأس أسود اللون، وشيلة نيلية، أو ذروة قطن ناعم وفي البيت ترتدي المرأة الإماراتية شيلة متعددة الألوان. | الكندورة: ثوب ترتديه المرأة تحت العباءة السوداء، وقد تكون مزركشة بالتلي. | العباءة: اللباس الخارجي للمرأة، وهي عدة أنواع، منها المصنوع من الحرير، والدفة مصنوعة من الصوف. | البرقع: نوع من القماش المقوى له لونان نيلي وأصفر تغطي به المرأة الإماراتية جزءًا من وجهها.'),
]
O['T3-L03'] = [
 ('ص 113 (ثالثًا: السنع الإماراتي المرتبط بلباس الرجل والمرأة - ومن السنع الإماراتي المرتبط بلباس الرجال)', 'تهنئة الشخص الذي يرتدي الكندورة الجديدة بكلمات مثل: مبروك الكندورة، تلبسها وتاخذ غيرها، ملبوس العافية، يعلها مبروكة، يعلك تلبسها وتلبس غيرها. | الالتزام بالزي الوطني باعتباره رمزًا من رموز الهوية الوطنية. | ارتداء العباءة (البشت) في بعض المناسبات مثل: الأعراس والأعياد والاحتفالات الوطنية. | للعقال رمزية خاصة، إذ يشير رفعه عن الرأس إلى الفخر والاعتزاز، مع عدم رميه على الأرض لأن في ذلك إهانة لصاحبه. | إطلاق العقال والغترة في الهواء دليل على النصر والفوز والناموس. | وضع العقال على الرقبة مؤشر على أن صاحبه لديه مشكلة ما، ويطلب العون والمساعدة.'),
 ('ص 113 (ومن السنع الإماراتي المرتبط بلباس المرأة)', 'الالتزام بالزي المعروف في كافة المناسبات التي تحضرها المرأة. | حرص النساء الإماراتيات على نقل الموروث المتعلق باللباس إلى البنات والحفيدات. | اهتمام المرأة الإماراتية بلباسها بالمظهر اللائق الذي يعكس واقعها ومكانتها الاجتماعية ووقارها. | يقتصر لباس البرقع في الوقت الحالي على بعض النساء، دون المساس بتاريخه ومكانته في لباس المرأة التقليدي، علمًا بأن البرقع كان مؤشرًا على أن من تلبسه وصلت إلى سن البلوغ والنضوج. | التزام المرأة الإماراتية بلباسها التقليدي في مختلف مواقع العمل والمناصب الرسمية، دليل على اعتزازها بالتراث وهويتها الوطنية.'),
]
O['T3-L04'] = [
 ('ص 116 (أولًا: سنع الدرب والمشي - المخوة)', 'فرضت حياة الصحراء على أبناء الإمارات قديمًا ضرورة الانتقال والترحال من مكان لآخر، لتوفير متطلباتهم الحياتية، وقد تنوعت أشكال السفر البرية والبحرية، وأوجدت عادات وتقاليد ونواظم مجتمعية متعارف عليها سواءً في الإعداد للسفر أو في الانتقال.'),
 ('ص 116', 'فمن السنع الإماراتي توزيع الأدوار بين رفقة السفر (المتخاوين) أو (الطروش)، والتزامهم بمبدأ المخوة وأعرافها، بحيث يعاب على الفرد أن يخل بأي مبدأ يسيء إلى (إخويّاه)، أو (رفاق الدرب) في الرحلة.'),
 ('ص 116', 'ومن السنع الإماراتي في هذا المجال (تأمير) شخص من بين المسافرين ممن يجدون فيه سمات القيادة والرأي السديد، والصفات الحميدة، ليتولى قيادة الرحلة. وهنا يتوجب على رفاقه الآخرين الطاعة له بعد المشورة فيما بينهم وإعانته على إنجاز كل ما يسند إليه من مهام ومسؤوليات.'),
 ('ص 116', 'أضف إلى ذلك أن من السنع الإماراتي في هذا المجال المشاركة في متطلبات وتكاليف السفر المادية والمعنوية، وهو ما يسمى ب(القطيّة) وهي مبلغ من المال يدفعه المشارك في الرحلة، في الوقت الحالي.'),
 ('ص 116 (آداب المشي)', 'فيما يتعلق بالسنع الإماراتي المتعلق بالمشي في الأسواق وغيرها من الأماكن العامة، يتوجب على الفرد احترام آداب الطريق والمارة والأمكنة، إذ من المعيب على الرجل أن يمسك يد رفيقه بالدرب، أو وضع يده على كتفه، ويعاب في هذا المجال على الإبن أن يتقدم على أبيه في المشي، أو أن يتقدم الصغير على الكبير.'),
 ('ص 116', 'وبالنسبة للرجل والمرأة أثناء السير معًا، عدم مشي الرجل خلفها بل إلى جانبها. زد على ذلك أن من آداب الطريق التي عرفها المجتمع الإماراتي منذ القدم، عدم الأكل أو الشرب أثناء السير في الشارع، فضلًا عن الاتزان في المشي، ومراعاة حقوق الآخرين في الطريق، والالتزام بالحشمة واللباس الإماراتي التقليدي سواءً بالنسبة للرجل أم المرأة.'),
 ('ص 117 (ومن آداب السنع الإماراتي في السفر)', 'المشاركة في تكاليف السفر ونفقاته بين رفاق الدرب أو السفر. | الالتزام بأصول المخوة والوقوف معًا في معالجة الصعاب والطوارئ المستجدة في السفر. | إعطاء الانطباع الجيد عن العادات والتقاليد الإماراتية الأصيلة، كون المسافر سفيرًا لبلده أينما انتقل، وحيثما حل. | تحمل الخوي لخويه في السفر، وعدم ترك الفرصة للغير للتدخل في العلاقة بينهما واستغلالهما ماديًا ومعنويًا. | الوقوف إلى جانب الخوي (رفيق الدرب)، في حال تعرضه إلى أي مشكلة أو موقف صعب، والحرص على عودته سالمًا إلى أرض الوطن.'),
]
O['T3-L05'] = [
 ('ص 117 (ثانيًا: سنع الإماراتيين في الخارج)', 'أسهم موقع دولة الإمارات العربية المتحدة بارتباطها بدول العالم قديمًا وحديثًا، وكان أبناء الإمارات على صلة دائمة بالشعوب القريبة والبعيدة لأغراض عديدة، مثل: التجارة والعمل، وأيضًا طلب العلم والعلاج والسياحة، ولقد عملت هذه الأساليب من وسائل التواصل مع الآخرين على تشكيل تقاليد وممارسات ترتبط بها.'),
 ('ص 117', 'ففي رحلات أبناء الإمارات التجارية في الماضي، قدموا أمثلة مميزة في العلاقة مع الآخرين، وعملوا على نشر القيم والتقاليد العربية والإسلامية، إضافة إلى معارفهم الواسعة بعلوم البحار والسفن والنقل البحري، وكان من أشهرهم «أحمد بن ماجد» الذي كان مرجعًا لبعثات الاستكشاف الغربية في مجال الملاحة وطرقها وأدواتها.'),
 ('ص 117', 'وقد تمسك الإماراتيون في صلاتهم التجارية بعاداتهم وتقاليدهم الحياتية، ونقلها بمسؤولية ووعي للشعوب التي حلوا بها، فكانوا مثال الأمانة والصدق والوفاء والالتزام بالعهد، تاركين صورة جلية ومشرقة لما يمكن أن يكون عليه العربي في الخارج.'),
 ('ص 117', 'ومنذ نشوء دولة الإمارات الحديثة على يد مؤسسها وباني نهضتها المغفور له -بإذن الله تعالى- الشيخ زايد بن سلطان آل نهيان إزداد ترابط أبناء الإمارات بالعالم العربي والإسلامي والغربي لدواعي عديدة من أهمها التعليم والبعثات الدراسية والسفر من أجل العلاج، وتمثيل الدولة في مختلف البعثات الدبلوماسية والهيئات والمنظمات الدولية.'),
 ('ص 118', 'وفي كل هذه المجالات حافظ الإماراتيون على سنعهم في المأكل والزي الوطني، إذ باتَ الإماراتي معروفًا في الخارج من بين الجاليات الأخرى من خلال سلوكياته وآدابه وحسن تعامله مع الآخرين.'),
 ('ص 118', 'ولنا أن نسوق العديد من المواقف والأمثلة حول تمسك أبناء الإمارات بتقاليدهم في الخارج، وهو جهد منوط بالحكومة الرشيدة من جهة، وبأبناء الإمارات من جهة أخرى، فالدولة عبر مؤسساتها المسؤولة وسفاراتها ومكاتبها الدبلوماسية والصحية والتعليمية حريصة كل الحرص على متابعة أبناء الدولة في الخارج كل حسب تخصصه.'),
 ('ص 118', 'وكثيرًا ما تدعو السفارة أبناءها المبتعثين إلى حفل تنظمه بمناسبة قدومهم، ولقد أسهم برنامج (تواجدي) الإلكتروني بتسهيل كل ما يتعلق بإجراءات الإماراتيين في الخارج. إن هذه الإجراءات المسؤولة تعبر بجلاء على عدم اقتصارها على الجهود التي يقدمها المسؤولون لأبناء الوطن في الداخل، بل تمتد إلى متابعتها وتلبيتها في الخارج.'),
 ('ص 118', 'من جانب آخر شكلت هذه الرعاية والمتابعة المثلى من قبل الدولة للمسافرين إلى الخارج سياجًا يحميهم من المخاطر أو الوقوع في مواقف مشبوهة تسيء إلى السنع الإماراتي والصورة الإماراتية النقية في الخارج.'),
 ('ص 118', 'وفي موازاة هذا الالتزام الرسمي إزاء أبناء الإمارات في الخارج، يقوم العديد من أبناء الإمارات بمشاريع وخدمات مشرفة للمسافرين، فتراهم يمدون يد العون لبعضهم بعضًا، وكثيرون أولئك الذين نقلوا السنع الإماراتي والتقاليد في المناسبات الوطنية والأعياد وغيرها من المناسبات الإجتماعية.'),
 ('ص 118', 'والأبعد من ذلك قيام بعض الموسرين ببناء مجالس ومساجد للرجال والنساء، مرفقة بالمستشفيات التي يحل فيها المرضى الذين يتلقون علاجهم في الخارج.'),
 ('ص 118-119', 'غير أن ما يبعث على الإعجاب والتقدير في موضوع تواجد أبناء الإمارات في الخارج للأسباب الآنفة، ما يقوم به أصحاب السمو والشيوخ في عيادة المرضى في مستشفياتهم في الخارج، إذ كثيرًا ما تفاجأ الأسرة الإماراتية المرافقة للمريض بزيارة أحد الشيوخ لها للإطمئنان على حالة المريض الصحية، وتذليل كل المعوقات التي تواجهه لاستكمال علاجه.'),
 ('ص 119', 'وهنا لابد من التذكير أن من مظاهر السنع الإماراتي في العلاج بالخارج، مرافقة المريض من قبل عدد من أفراد أسرته وأقربائه في تقليد اجتماعي قل نظيره في المواساة والترابط على صعيد الأسرة الأولية والأسرة الممتدة.'),
 ('ص 119', 'وغير بعيد عن هذه التقاليد التزام الإماراتيين بالخارج بلباسهم الوطني أو زيهم التقليدي بكل سمو واعتزاز، سواء بالنسبة للرجال أو النساء.'),
 ('ص 119', 'وحقيبة المسافر الإماراتي قلما تخلو من دلال القهوة والفناجيل، والعود، والعطور التقليدية، والغترة والعقال والكندورة والوزار، والعباءة والشيلة بالنسبة للنساء.'),
 ('ص 119', 'وكم يبدو الترابط بين أبناء الإمارات جليًا في شتى المناسبات الوطنية والاجتماعية التي يصادف حدوثها أثناء تواجدهم في الخارج، إذ تتحول طقوس المناسبة إلى مناسبة اجتماعية وثقافية للتعارف فيما بينهم وممارسة فنون الأداء التي ورثوها عن الآباء والأجداد كالعيالة، والرزفة، وغيرها.'),
 ('ص 119', 'وهكذا يحرص الإماراتيون على المحافظة على قيمهم وتقاليدهم وسنعهم في الوطن وخارجه، وكأنها أمانات في أعناقهم، وجزء من نسيجهم الاجتماعي والثقافي والوطني.'),
]
O['T3-L06'] = [
 ('ص 122 (المحور الثالث عشر: السنع الإماراتي في الهوايات التراثية)', 'عرف المجتمع الإماراتي العديد من الرياضات التراثية الفردية والجماعية، وعمل على المحافظة عليها كوسيلة من وسائل إشباع الهوايات والترويح عن النفس، وتمضية أوقات الفراغ، والاستمتاع بالطبيعة بما هو ممتع ومفيد. ومن أبرز هذه الهوايات وأكثرها شعبية (رياضة الصيد بالصقور) وسباق الهجن والفروسية وسباق المراكب الشراعية.'),
 ('ص 122 (أولًا: سنع القنارة - رياضة الصيد بالصقور)', 'الصقر: طائر من بين الطيور الجارحة التي تتميز بصفات جسمانية خاصة، تجعله قادرًا على الطيران لمسافات بعيدة، وعلو شاهق، إضافة لبصره الحاد ومناورته الفريسة واصطيادها. والأبرز في الصقر هو إمكانية ترويضه وجعله شريكًا حقيقيًا للصياد في مغامرة القنص الممتعة.'),
 ('ص 122', 'ساعدت بيئة الصحراء الممتدة على ظهور هذه الرياضة واستدامتها على مر الزمان، وهي من بين الرياضات التي مارسها الحكام والشيوخ وأبناء المجتمع، لهذا اكتسبت مكانة خاصة، وحافظت على سنعها عبر الأجيال. ففي الصقارة تبرز العلاقة بأبهى صورها ومضامينها بين أربعة أطراف، هي: الصقر - الصقار - الطبيعة - الطريدة. ولأهمية الصقارة لقيت كل دعم وتعزيز من قبل أصحاب السمو الشيوخ حكام الإمارات، وفي طليعتهم الصقار الأول الشيخ زايد بن سلطان آل نهيان -طيب الله ثراه، الذي كان له في هذه الرياضة مآثر وتقاليد وأعراف شكلت دائمًا دستورًا للصقارين للحاضر والمستقبل.'),
 ('ص 122 (أنواع الصقور - معلومات إثرائية)', 'عرف المجتمع الإماراتي أنواعًا من الصقور، من بينها: 1. الحر: طائر صبور، وقوي، يمتلك طاقة خاصة، من أسرع الطيور في المسافات البعيدة، قناص ماهر لطريدته، يتحمل الجوع، ذو بأس شديد، هادئ، وقنوع. | 2. الشاهين: من الطيور البحرية التي تتغذى على طيور الماء. من فصيلته "وكري الشواهين" و"تبع الشواهين"، ومن أبرز صفاته: عدم قدرته على تحمل الجوع، سرعة الغضب والنفور، أصغر حجمًا من الحر وأقل قدرة منه على تحمل التعب، لكنه أسرع الجوارح في المسافات القصيرة.'),
 ('ص 123', '3. القرموشة: ذكر الصقر في الحر ذات حجم صغير متعددة الألوان تتحمل الصعاب تستطيع صيد كل ما يصيده الحر والوكري. | 4. الوكري: ومنه وكري الحر ووكري الشواهين، فوكري الحر أقل من الحر العادي من حيث الحجم، والبعض يساويه في الحجم. وهو طائر شرس، يتميز بسواد عينيه، واحمرار قمة شعر رأسه، ويصطاد كل ما يصطاده الحر. أما وكري الشواهين فحجمه أقل أو يساوي حجم الشاهين العادي أحمر الرأس، عيناه مائلتان للأصفر، أما ألوانه بشكل عام فهي ألوان الشاهين، قابل للتعليم، ومزاجه أبرد من مزاج الشاهين. | 5. تبع الشواهين: ينتمي إلى السلالة الثالثة من الشواهين، وأقل من الشاهين والوكري من حيث الحجم.'),
 ('ص 123 (اقتناء الصقر وترويضه)', 'يحرص الصقارون على اقتناء أنواع جيدة من الصقور، إما باصطيادها بإحدى الطرق التقليدية المعروفة، وهي: طريقة التكويخ، أو طريقة الصيد بالشباك، إضافة لإمكانية الحصول على الصقر بشرائه من الأسواق المخصصة للبيع، أو من خلال هدية تقدم له من صقار آخر.'),
 ('ص 123', 'ويمكن ترويض الصقر وتدريبه وفق إجراءات تنقله من طبيعته البرية إلى الألفة والاستئناس، وتقبل الناس وأصواتهم. ومن بين هذه الإجراءات ما يلي: استلام الطير من مصدره (الصيّاد أو البائع أو المهدى منه). | وضع البرقع على عيني الصقر. | ربطه بالسبوق ثم المرسل. | وضعه على اليد اليسرى المحمية بالمنقلة. | إطعام الطير وهو على يد صاحبه بما يسمى ب (تنسير الطير). | تسميته، ومناداته بالاسم الذي تم اختياره ليعتاد عليه. | التدرج في تدريبه ليعتاد على الضوضاء والاستجابة لصوت صاحبه.'),
 ('ص 123', 'تنسير الطير: عملية يقوم بها القناص بإطعام صقره من خلال تقديم قطع من اللحم الطازج له بهدف تعويده على الوقوف على المنقلة، واستئناس صاحبه، وبعد تدريبه على الصيد، يصبح التنسير جزء من الفريسة، ليعتاد على صيدها، والحصول على غذائه منها.'),
 ('ص 124', 'التدريب المتدرج على صيد الفريسة عن قرب، ثم عن بعد، باستخدام التلواح (وهو جناح طائر الحبارى)، ليعتاد عليه وما فيه من طعام، ويتضمن التدريب أيضًا إجهاد الطير ليكون قادرًا على تحمل الصعاب أثناء مطاردة فريسته. وهناك ما يعرف ب (الطير الربيب)، وهو طير هادئ، قليل الحركة، لا يخفق بجناحيه، وغير مزعج عندما يحمله الصقار، صغيرًا أم كبيرًا.'),
 ('ص 124 (أدوات الصقار)', 'يستخدم الصقار أدوات خاصة في رحلة القنص، ومن أهمها: البرقع: أداة تصنع من الجلد، لحجب الرؤية عن الطير أثناء عملية الترويض وغير ذلك. | المنقلة: واق يضعه الصقار في يده ليحمل عليه الصقر دون أن يسبب له أي أذى. | الدس: قفاز أو كف يلبسه الصقار في يده لحمايتها من مخالب الصقر ومنقاره. | السبوق: خيطان يربط طرفاهما في رجلي الصقر لمنعه من الانطلاق. | المرسل: خيط يربط طرفه بالسبق وطرفه الآخر بالوكر. | التلواح: جناح الحبارى يربط بخيط لتدريب الصقر، أو استدعائه عند الضرورة. | الوكر: وتد من الحديد مخروطي الشكل، يستخدم لوقوف الصقر عليه. | المخلاة: حقيبة من القماش، يضع فيها الصقار أدوات الصيد اللازمة.'),
 ('ص 124 (الاستعداد لرحلة القنص)', 'تمتد رحلة القنص من أسبوع إلى شهر أو أكثر من ذلك في بعض الأحيان، وتبدأ بالتحضير لها بدءًا من اقتناء الطير وتدريبه وتأهيله وفق الخطوات التي سبق ذكرها، ومرورًا باختيار الصقارين للمخوة، وتحضير أدوات ولوازم الرحلة بما في ذلك الطعام (مؤونة الرحلة)، والبرنامج الذي سيتم تنفيذه فيها، وفي حال كانت رحلة المقناص بمعية شيخ يكون هو القائد والموجه في الرحلة، وفي حال كانت الرحلة عادية لا يقودها أحد الشيوخ يتضمن الاستعداد لها باختيار قائد من بين المشاركين ليأتمر الجميع بأمره.'),
 ('ص 124-125', 'الجدير بالذكر أن الغاية من رحلة القنص ليس الحصول على الفرائس أو الطرائد، وتوفير الغذاء، إنما هي رياضة مجتمعية ضاربة في أعماق التاريخ، هدفها الترويح عن النفس وضغوط الحياة، وإشباع الهوايات بما يرافقها من سنع وتقاليد، من أبرزها: بث روح الألفة والتآلف بين الصقارين بما فيهم الشيخ قائد الرحلة. | خلق علاقة بين مجموعة الصقارين قائمة على التفاهم والصراحة والتسامح. | جعل رحلة القنص مناسبة للتنافس والإثارة تارة، وخيبة للأمل تارة أخرى، وهذا يعني تقبل الهزيمة بروح رياضية كما تقبل الفوز والنجاح، وغير ذلك من المفاجآت. | التعاون بين الصقارين في كل شؤون الرحلة، وخلق أجواء من المرح والمتعة والود والتسامح. | الاستئناس بتقاليد القنص، ومنها: إشعال النار، وتبادل الأحاديث والحكايات في أجواء من السمر، وصنع القهوة العربية، والطعام، والتكيف مع الطبيعة، والاستمتاع بأجوائها البهيجة. | الالتزام بشكل طوعي بالمهام والمسؤوليات الملقاة على الصقارين بما في ذلك هد الطير (أي إطلاقه لمطاردة الفريسة)، وتنبيه الصقار للآخرين بكلمة "دونك"، ومن ثم كلمة "إلزم" إشعارًا له بإطلاق طيره.'),
 ('ص 125', 'هد: كلمة يقولها الصقار لزميله بأن يطلق صقره خلف الطريدة، في إطار توزيع الأدوار بينهم. | الزم: لفظة متعارف عليها بين الصقارين تعني التزام الصقارين بعدم إطلاق طيورهم خلف الطريدة في حال بادر أحدهم أولًا بإطلاق طيره مع ترديد كلمة إلزم.'),
 ('ص 125', 'ومن السنع عندما ينجح أحد الصقارين في اصطياد الحبارى أن يهنئه زملاؤه الآخرون بكلمة "انطلق الصيد"، فيرد: "كفيت الغلق، أو كفيتم الغلق". | توزيع (الهد) بين أعضاء الرحلة لتوفير الفرصة أمام الجميع للاصطياد، إذ من المعيب في سنع الصقارين أن يهد أحدهم طيره خلف طير صاحبه. | معاملة الطير بالرأفة والحسنى، إبعاده عن النار والدخان، ورعايته، والتقرب منه، وعدم إرهاقه، والإساءة إليه. | مراعاة حاجة الطير للطعام، من خلال مشاهدات الصقار لصقره أو من خلال تنبيه زملائه له بالقول: "طيرك مزري" أي (ضعيف)، وفي هذه الحالة يطلب من الصقار أن يتبن طيره.'),
 ('ص 125', 'تبن الطير: عبارة تقال لصاحب الصقر في حال كان طيره جائعًا، وذلك لإطعامه حتى الإشباع.'),
 ('ص 126', 'في حال عدم تمكن الصقر من الإمساك بطريدته، أو تعرضه إلى (الطمل) من الحبارى، يعز الصقار إلى زميله بأن يطلق صقره لملاحقة الطريدة عبر ما يعرف بعملية التلقيف. | الطمل: مادة لزجة تفرزها الحبارى في حال ملاحقة الصقر لها، مما يؤدي إلى شل حركة جناحيه، وعدم قدرته على الطيران. | التلقيف: هو إطلاق صقر آخر وراء الطريدة في حال عجز الصقر الأول عن اللحاق بها، أو تعرضه لطملها.'),
 ('ص 126', 'المشاركة في تكاليف رحلة القنص التي يعدها مجموعة من الأفراد بما يعرف (القطية). | الالتزام بمواعيد القنص اليومية، حيث تبدأ الفترة الصباحية عادة من الساعة السادسة صباحًا وحتى الحادية عشرة، والفترة المسائية من الساعة الثالثة ظهرًا وحتى الخامسة مساءً. | الالتزام بقواعد القنص كهواية، وعدم الإفراط بالصيد، والإساءة للبيئة. | من السنع الإماراتي مساعدة الصقار الذي فقد طيره لسبب ما كالضباب أو الموت، وتعويضه من قبل زملائه الآخرين بمنحه طيرًا آخر. | توسير الطير، في حال تعرض ريشه للكسر أو الالتواء بغرض المحافظة على مهاراته في القنص. | عدم الإساءة إلى الجماعات التي تعيش في منطقة القنص، وتعكير نمط حياتهم المعتادة، إضافة لتقديم العون والمساعدة لهم. | اعتبار رحلة القنص مناسبة لإبراز العادات والتقاليد الإماراتية بصورة مشرفة، وتعريف الآخرين بالسلوم والسمت الإماراتي. | الاهتمام بالطير طوال فترة المقيض، التي يتم من خلالها قيام الطير بتبديل ريشه، وتستغرق هذه العملية مدة من 5 إلى 6 أشهر.'),
]
O['T3-L07'] = [
 ('ص 127 (ثانيًا: السنع المرتبط بالهجن)', 'شكلت الإبل أحد المقومات الأساسية للتراث الإماراتي، إضافة لشجرة النخيل والغوص والصحراء. فمنذ القدم وقفت إلى جانب أبناء الإمارات تتحمل معهم مشاق السفر والارتحال، وتوفير احتياجاتهم الغذائية والمعيشية بكل صبر ووفاء. كما كانت من جانب آخر وسيلتهم للترويح عن النفس في العديد من الرياضات التراثية.'),
 ('ص 127', 'ولئن كان الحديث عن الإبل وتربيتها موضع آخر غير ما نحن في صدده في هذا الكتاب، فإننا سنحصرها في الحديث هنا مباشرة بالسنع المتوارث في مجتمع الإمارات المرتبط بتربية الإبل، وفق النقاط الآتية:'),
 ('ص 127', 'هناك فرق بين الناقة والمطية في التقاليد الإماراتية، فالناقة هي التي تربى عادة من أجل الحصول على حليبها ووبرها ولحمها، بينما تسنع المطية وتؤدب، لاستخدامها في الركوب أو الركض (السباق). | كل أنواع السنع المرتبط بالمطية مثل: خطم المطية، وضع الشداد، ركوبها، يتم من الجهة اليسرى لها. | اقتياد المطية من قبل صاحبها يتم باليد اليمنى. | حلب الناقة يتم عادة من الجهة اليسرى لها، بينما رضاعة حوارها فتتم من جهتها اليمنى.'),
 ('ص 127', 'المنيحة: تقليد اجتماعي يقوم به الإماراتيون في مساندة بعضهم بعضًا، إذ قد يمنح أحد المقتدرين ناقةً، لشخصٍ آخر محتاج للاستفادة من حليبها لفترة ما.'),
 ('ص 127', 'الوديعة: سنع إماراتي يتمثل في تربية وتأهيل هجن السباق، حيث من المتعارف عليه أن يقوم صاحب المطية بإيداعها لدى شخص آخر لإعدادها في الوقت الحاضر كما كان من المتعارف عليه إيداع الإبل أو الحلال عند شخص آخر - أثناء غياب صاحبها لسفر أو عمل، مقابل مكافأة يتم الاتفاق حولها.'),
 ('ص 127-128', 'عندما تفوز مطية أحد المتسابقين يتلقى التهنئة من قبل المتسابقين الآخرين، ومن السنع الذي يقال له في هذه المناسبة: "تستحق الناموس"، فيرد: "يحق لك خير" أو "تستحق خير". | في حال قدم شخص إلى عزبة شخص آخر في وقت حلب البوش، يتوجب على صاحب العزبة أن يقدم لضيفه أو ضيوفه المتواجدين الحليب، بدءًا من الشخص الكبير، قائلًا: "العون"، فيرد هذا الشخص: "كفيت الهون، والله يبارك فيهن".'),
]
O['T3-L08'] = [
 ('ص 128 (ثالثًا: السنع المرتبط بالفروسية)', 'لا يمكن الحديث عن الرياضات التراثية في مجتمع الإمارات دون إبراز أهمية الخيول في هذه الرياضات، وهي أهمية متأصلة عبر التاريخ، ومن هنا كانت الدعوة إلى اقتناء الخيل وتربيتها واستخدامها.'),
 ('ص 128', 'وتربية الخيول مكون أساسي من مكونات التراث والسنع الإماراتي الأصيل، إذ نظمت في وصفها الأشعار، وتواردت في شأنها الحكايات. على صهواتها تبارى الفرسان في ساحات المعارك، وفي أصالتها وتحديد سلالاتها اشتغل الخبراء والمؤرخون، والخيول والإبل من أبرز الحيوانات التي أعانت سكان الصحراء على مواجهة العديد من صعاب الحياة.'),
 ('ص 128', 'وما من شك في أن الأغراض أو الأهداف من تربية الخيول تغيرت بمرور الزمن، وهذا شأن الكثير من جوانب التراث في العديد من المجتمعات. وحرصًا من القيادة الرشيدة في دولة الإمارات العربية المتحدة على الحفاظ على تراثها، ومنه تربية الخيول أنشئت النوادي والميادين والمراكز الطبية والبيطرية، والمراكز العلمية المتخصصة بإنتاج سلالات أصيلة تبعًا للأغراض من تربيتها. وفي مقدمة ذلك المكانة التي حظيت بها الخيول قديمًا وحديثًا، والتي يلخص جانبٌ منها بيت الشعر النبطي الآتي: (بيت شعر نبطي في الكتاب)'),
 ('ص 129 (ومن ألوان السنع الإماراتي المرتبط بالخيل)', 'ظهور خبراء إماراتيين متخصصين في سلالات الخيل وأمراضها وطرق علاجها. | استخدام الخيول في السباقات الشعبية التي كانت تقام في الأعياد والأعراس. | استخدام الخيول في حفظ الأمن والنظام والاستطلاع. | ظهور سلالات عريقة من الخيول العربية، وانتشارها في العالم. | تبادل إهداء الخيول بين الحكام كان على الدوام من أسمى الهدايا وأكثرها قيمة، إذ يتداول المؤرخون أن الشيخ زايد الأول كان في إسطبله الخاص في قلعة الجاهلي أكثر من 150 رأسًا من الخيول الأصيلة، ومن أشهر هذه الخيول الحصان (ربدان) الذائع الصيت. | المشاركة في السباقات العالمية للخيول، وفوز الخيول الإماراتية في العديد منها، ومن بين هذه السباقات كأس دبي العالمي للخيول. | إقامة سباقات القدرة والتحمل للتأكيد على الدور الذي لعبته الخيول في الماضي، من حيث كونها وسيلة من وسائل الانتقال في الصحراء، وقطع المسافات الشاسعة.'),
]
O['T3-L09'] = [
 ('ص 129 (رابعًا: سنع البحر)', 'شكل البحر لأبناء الإمارات واجهة أمامية للكثير من موارد الرزق والعيش، فمثلما كانت الصحراء ظهيرهم ومصدر رزقهم في الري والزراعة. بقي البحر بمكنوناته وخيره الوفير مقصدهم دائمًا في الغوص والصيد والتجارة، وهكذا عاش أبناء الإمارات في كنف البحر والبر على حد سواء.'),
 ('ص 129', 'ومثلما رأينا ألوانًا عديدة من السنع في البر تجلت في جوانب اجتماعية واقتصادية وثقافية حافظت على علاقتهم بهذا البر، وبقيت وفية له سلوكًا وانتماءً واعتزازًا، كان ولا يزال لأبناء الإمارات عشق خاص بالبحر، تتناقله الأجيال بأمانة من جيل إلى جيل، ولكي نقف على واقع السنع البحري الإماراتي حري بنا أن نتتبع تقاليد رحلات الغوص والتجارة البحرية، وفق منهجية تقودنا إلى ما نروم إليه في الكشف عن مظاهر هذا السنع وجوانبه المختلفة.'),
 ('ص 129', 'فالسنع المرتبط بالغوص على اللؤلؤ تبدأ فصوله وخطواته من الإعداد لرحلة الغوص بكل ما تكتنفه هذه الرحلة من مشاعر الوداع عند الزوجة والأولاد، والأهل، والأحبة، والأقرباء.'),
 ('ص 130', 'وهنا يتجلى السنع بقيام النوخذة بتزويد الغاصة وغيرهم من طاقم السفينة المكون من: الغواص، والسيب، واليلاس، والمجدمي، والنهام، وغيرهم، باحتياجات أسرهم من المير اللازم لهم لفترة قد تستغرق ثلاثة أشهر.'),
 ('ص 130', 'أما المشهد الثاني من مشاهد السنع لرحلة الغوص فيتمثل بالرابطة الاجتماعية الفريدة في معانيها ومشاعرها، حيث يخرج سكان المدينة صغارهم وكبارهم، رجالهم ونساؤهم في صورة عفوية وعاطفية، لوداع سنيار البحر، ترجمها الشاعر الإماراتي الكبير سعيد بن عتيج الهاملي، بالأبيات المؤثرة الآتية: (أبيات شعرية في الكتاب)'),
 ('ص 130', 'أما المشهد الثالث للسنع المرتبط برحلة الغوص، فيستدل عليه بالتعاون والمخوة والعمل الجماعي الذي يربط طاقم السفينة بعضهم ببعض، في منظومة متعارف عليها، يقود إيقاعها النوخذة بكل أبوة وحكمة واقتدار.'),
]
